  Skill_117314_AwakerSkillBackgroundStory = {
    Text = "La loro colpa è provata dal fluire del loro nero sangue divino. Saranno giudicati, poiché solo attraverso la purificazione potranno entrare nella terra pura. Quindi giudicali. Dichiara i loro peccati. Libera il loro sangue. Che il giudizio cada sulle loro teste. Questo è il potere—e il solenne dovere—del Divus."
  },
  Skill_117314_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno [Arg2] volte. Questa carta viene automaticamente aggiunta alla tua mano quando si entra nel Turno Ultra."
