  },
  Skill_117315_BattleDesc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN e ottieni 3 cariche di <ZuiyinKeywords:Marchio del Peccato>. Dopo averla giocata, rimescola questa carta in cima al Mazzo di Pesca. Alla 3ª giocata, <DepleteIconKeywords:Consumo> e fa' sì che la tua prossima carta di comando benefici dell'effetto \"Espiazione nel Dolore\" ([Arg2]/3)."
  },
  Skill_117315_BattleDesc_3 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN e ottieni 3 cariche di <ZuiyinKeywords:Marchio del Peccato>. Dopo averla giocata, rimescola questa carta in cima al Mazzo di Pesca. Alla 3ª giocata, <DepleteIconKeywords:Consumo> e applica l'effetto \"Espiazione nel Dolore\" alla prossima carta di comando, attivandolo 2 volte ([Arg2]/3)."
