  Skill_117315_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN e ottieni 3 cariche di <ZuiyinKeywords:Marchio del Peccato>. Dopo averla giocata, rimescola questa carta in cima al Mazzo di Pesca. Alla 3ª giocata, <DepleteIconKeywords:Consumo> e consenti alla prossima carta di comando di beneficiare dell'effetto \"Espiazione nel Dolore\"."
  },
  Skill_117315_Desc_3 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN e ottieni 3 cariche di <ZuiyinKeywords:Marchio del Peccato>. Dopo averla giocata, rimescola questa carta in cima al Mazzo di Pesca. Alla 3ª giocata, <DepleteIconKeywords:Consumo> e fa' sì che la tua prossima Carta di comando benefici dell'effetto \"Espiazione nel Dolore\", applicandolo 2 volte."
