  Skill_117316_PropertyNameList = {
    Text = "DEF*GrowValue1,$GrowValue2"
  },
  Skill_117317_AwakerSkillBackgroundStory = {
    Text = "\"Pollux, il tuo sacro cuore porta lo splendore stesso del Portatore di Luce. Custodisci questa gloria come se venerassi Lui.\"\nE così, si pose la corona di menzogne sul capo, senza mai osare cedere.\n\"Pollux, non avere paura. Va', e assapora per me cos'è la libertà...\"\nEppure attraverso questa gloria ottenne tutto, e a causa di essa perse tutto. Alla fine, vide la corona per ciò che era: catene invisibili.\nCosì fece a pezzi la corona. Per la prima volta, il suo cuore vuoto brillò di una luce luminosa come il giorno—ma quei lamenti furiosi non potevano più raggiungere le orecchie della sua altra metà."
  },
  Skill_117317_Desc = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno a tutti i nemici. La tua prossima Carta di comando di Pollux in questo turno ottiene \"Espiazione nel Dolore\". Metti 1 <DerivativeCardKeywords_118:\"Sacro Cuore\"> in mano."
  },
  Skill_117317_EffectNameList = {Text = "Danno"},
  Skill_117317_Name = {
    Text = "Verdetto Sacro dell'Innocenza"
  },
  Skill_117317_OverLimitUtlSkillDesc = {
    Text = "Infliggi <Damage:[Damage:Arg1]> punti di DAN a tutti i nemici, permettendo alla tua prossima Carta di comando in questo turno di beneficiare dell'effetto \"Espiazione nel Dolore\". Metti 2 <DerivativeCardKeywords_118:\"Sacro Cuore\"> nella tua mano. In questo turno, ogni Carta di comando di Pollux ottiene un ulteriore 50% dell'effetto \"Espiazione nel Dolore\", e la tua prossima Carta di comando si attiva 1 volta aggiuntiva."
  },
  Skill_117317_PropertyNameList = {
    Text = "ATK*GrowValue1"
  },
  Skill_117318_AwakerSkillBackgroundStory = {
    Text = "In passato, i suoi occhi erano avvolti dall'oscurità, e così scambiò quell'oscurità per la luce del giorno. Ma vedendo la verità, si voltò e percorse il cammino opposto. Perché ora comprende: qualunque sia la direzione, i suoi passi sono sempre stati guidati dalla luce."
  },
  Skill_117318_Desc_0 = {
    Text = "Pollux ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Quando giocata e dopo la Fase di Scarto, ottieni 3 accumuli di <ZuiyinKeywords:Marchio del Peccato>; per ogni carta in mano, ottieni 1 accumulo aggiuntivo di <ZuiyinKeywords:Marchio del Peccato>."
  },
  Skill_117318_Desc_15 = {
    Text = "Pollux ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni 3 accumuli di <ZuiyinKeywords:Marchio del Peccato> quando giocata e dopo la fase di scarto, più 1 accumulo aggiuntivo per ogni carta in mano. \"Sacro Cuore\" infligge Sanguinamento pari al 100% del Danno. Dopo essere stata rimescolata nel Mazzo di Pesca giocando una carta, il Costo di Arithmetica di quel \"Sacro Cuore\" diventa 0 questo turno e applica <BleedingIconKeywords:Sanguinamento> pari al 100% del Danno."
  },
