  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "È arrogante, usa l'orgoglio per mascherare il vuoto irreparabile dentro di sé. Ha dimenticato chi era un tempo, e ha dimenticato chi avrebbe dovuto essere. Innumerevoli seguaci si inchinano ai suoi piedi, eppure negli echi della loro venerazione, dimentica la verità più cruciale: si è già sottomessa a questo pallido destino."
  },
  Skill_119763_BattleDesc = {
    Text = "Ottieni 2 Arithmetica e pesca 2 carte. Subisci [Arg3] <SacrificeKeyWord:Sacrificio> all'inizio del prossimo turno. <RippleKeywords:Onda d'Urto Residua>: Rimuovi [Arg4] <SacrificeKeyWord:Sacrificio>."
  },
  Skill_119763_Desc = {
    Text = "Ottieni 2 Arithmetica e pesca 2 carte. Subisci <SacrificeKeyWord:Sacrificio> pari al [Arg1]% dei PV Max all'inizio del prossimo turno. <RippleKeywords:Onda d'Urto Residua>: Rimuovi accumuli di \"Sacrificio\" pari al [Float:Arg2]% dei PV Max."
  },
  Skill_119763_EffectNameList = {
    Text = "Rimozione Sacrificio"
  },
  Skill_119763_Name = {
    Text = "Inni dell'Abisso"
  },
  Skill_119763_PropertyNameList = {
    Text = "$GrowValue1%"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "Le origini della scultura d'avorio nelle mani di Murphy sono oggetto di ampio dibattito. Alcuni sostengono che sia stata recuperata dalle rovine sottomarine da lei guidate, mentre altri sussurrano che sia nata insieme al Feto Divino dal cuore pulsante nel suo petto. Innegabilmente, questa scultura—simbolo del legame intricato tra lei e la città silenziosa di Lemuria che giace sotto l'oceano privo di luce—apparve agli occhi dei Navigatori il giorno in cui Murphy fu dichiarata la \"Vera Madre Divina\". Da allora, i fedeli osservarono Murphy brandire la scultura d'avorio per sfondare mari tempestosi e fendere l'oceano di sangue. Il potere assoluto trascende la mera illusione; le ginocchia dell'umanità possono solo inchinarsi davanti alla forza assoluta."
  },
  Skill_119764_BattleDesc = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. Subisci [Arg7] <SacrificeKeyWord:Sacrificio> all'inizio del turno successivo. Infliggi [Arg3] cariche di <DwmofeiKeywords:Rituale di Nascita> a tutti i nemici. Infliggi <Damage:[Damage:Arg5]> DAN [Arg4] volte al nemico con PV più alti, che beneficia di un bonus del [Arg6]% ai <TentacleInjurieIconKeywords:DAN Tentacolo>."
  },
  Skill_119764_Desc = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. Subisci <SacrificeKeyWord:Sacrificio> pari al [Arg2]% dei PV massimi all'inizio del turno successivo.\nInfliggi [Arg3] cariche di <DwmofeiKeywords:Rituale di Nascita> a tutti i nemici. Infliggi <Damage:[Damage:Arg5]> DAN [Arg4] volte al nemico con PV più alti, che beneficia di un bonus del [Arg6]% ai <TentacleInjurieIconKeywords:DAN Tentacolo>."
  },
  Skill_119764_EffectNameList = {
    Text = "Scudo,Rituale di Nascita,DAN,Bonus DAN Tentacolo"
  },
  Skill_119764_Name = {
    Text = "Principessa delle Illusioni"
  },
  Skill_119764_OverLimitUtlSkillDesc = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. Subisci [Arg7] <SacrificeKeyWord:Sacrificio> all'inizio del turno successivo. Infliggi [Arg8] cariche di <DwmofeiKeywords:Rituale di Nascita> a tutti i nemici. Infliggi <Damage:[Damage:Arg5]> DAN [Arg4] volte al nemico con PV più alti, che beneficia di un bonus del [Arg6]% ai <TentacleInjurieIconKeywords:DAN Tentacolo>. Genera 3 \"Valzer di Lemuria\" con Costo di Arithmetica 2, con <PrepareKeypvewords1: Preparazione 1> e <DepleteIconKeywords:Consumo>."
  },
  Skill_119764_PropertyNameList = {
    Text = "DEF*GrowValue1,$GrowValue2,ATK*GrowValue3,$GrowValue4%"
  },
  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "È frivola, usa la leggerezza per combattere contro una realtà in frantumi. \"Danziamo,\" comandò, \"una danza dedicata al Signore. RingraziamoLo per averci concesso una causalità perversa, un passato caotico e un futuro sfuggente.\" Sotto i riflettori, è l'unico centro di tutta l'esistenza."
  },
  Skill_119765_BattleDesc = {
    Text = "Ottieni <Posse:[Arg7]> Keyflare. Attiva effetti diversi in base alla Postura del tentacolo attuale:\n\"Maree crescenti\": <TentacleInjurieIconKeywords:DAN Tentacolo> +[TentaclePower:Arg1], genera 1 Tentacolo.\n\"Mare Tranquillo\": Ottieni <Block:[Block:Arg2]> Scudo, conserva il 50% dello Scudo al turno successivo.\n\"Onde Furiose\": Infliggi <Damage:[Damage:Arg4]> DAN [Arg3] volte al nemico con PV più alti, che beneficia di un bonus del [Arg5]% ai DAN Tentacolo."
  },
  Skill_119765_Desc = {
    Text = "Ottieni Keyflare pari al [Arg6]% della Rigenerazione Keyflare. Attiva effetti diversi in base alla Postura del tentacolo attuale:\n\"Maree crescenti\": <TentacleInjurieIconKeywords:DAN Tentacolo> +[TentaclePower:Arg8], genera 1 Tentacolo.\n\"Mare Tranquillo\": Ottieni <Block:[Block:Arg9]> Scudo, conserva il 50% dello Scudo al turno successivo.\n\"Onde Furiose\": Infliggi <Damage:[Damage:Arg4]> DAN [Arg3] volte al nemico con PV più alti, che beneficia di un bonus del [Arg5]% ai DAN Tentacolo."
  },
  Skill_119765_EffectNameList = {
    Text = "Danno Tentacolo,Scudo del Personaggio,Danno,Bonus Danno Tentacolo,Ricarica Keyflare"
  },
  Skill_119765_Name = {
