  Skill_119766_AwakerSkillBackgroundStory = {
    Text = "Versò il sangue ombelicale divino nel mare, pregando il Signore per un viaggio che non avrebbe mai raggiunto la sua destinazione. Finché le bolle dei sogni persistono, lei rimane l'unica e sola Madre Divina."
  },
  Skill_119766_Desc_0 = {
    Text = "Murphy: Falsonata ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Murphy: Falsonata infligge il [Arg2]% del Danno che infligge come accumuli di <SacrificeKeyWord:Sacrificio> sul bersaglio. A inizio turno, ottiene 1 accumulo di <MingqiKeywords:Patto>."
