  Skill_122485_Desc_0 = {
    Text = "Mouchette ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Istanze di Danno di \"Incontro Drammatico\" +2. Ogni volta che \"Incontro Drammatico\" viene attivato, Danno Finale Temporaneo dei \"Colpo\" di Mouchette +25%. Genera immediatamente 1 \"Esplosione Mortale\" Temporanea."
  },
  Skill_122485_Desc_15 = {
