  },
  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "Non parlano mai della sua origine; parlano solo dell'Estasi Indescrivibile che annunciò la sua nascita.\nLa tua coscienza si dissolverà nel rapimento; il tuo passato si dissolverà nel rapimento; il tuo cranio si dissolverà nel rapimento... il tuo stesso cervello si scioglierà nell'estasi.\nUna prelibatezza che si scioglie in bocca—con il \"Desiderio\" come catalizzatore."
  },
  Skill_125371_BattleDesc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno a tutti i nemici come Colpo Critico garantito e infliggi [Arg2]% Veleno. <ResonanceKeywords:Risonanza 3>: <EmbryoFusionIconKeywords:Fusione Embrionale> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_BattleDesc_1 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno da Colpo Critico garantito a tutti i nemici e infliggi [Arg2]% Veleno, <EmbryoFusionIconKeywords:Fusione Embrionale>+ [Arg6]. <ResonanceKeywords:Risonanza 3>: <EmbryoFusionIconKeywords:Fusione Embrionale> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno da Colpo Critico garantito a tutti i nemici e infliggi [Arg2]% Veleno. <ResonanceKeywords:Risonanza 3>: <EmbryoFusionIconKeywords:Fusione Embrionale> +[Arg4]."
  },
  Skill_125371_Desc_1 = {
