  },
  Skill_125375_Name_1 = {
    Text = "Convegno velato"
  },
  Skill_125376_AwakerSkillBackgroundStory = {
    Text = "Attraverso i secoli, la parola \"Amore\" non è stata altro che un canto di sirena, che attira le anime verso un mare di peccato dal quale rifiutano di tornare."
  },
  Skill_125376_Desc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Riduci temporaneamente la <ExhaustionIconKeywords:FOR> di tutti i nemici di [Exhaustion:Arg1].] Ottieni [Arg2] Arithmetica e infliggi [Poison:Arg3] accumuli di <IntoxicationIconKeywords:Veleno> a tutti i nemici. Scegli: <WitherKeywords1:Promettere> o <WitherKeywords2:Ammaliare>."
  },
  Skill_125376_Desc_3 = {
    Text = "[<DevouredIconKeywords:Divorare> : riduce temporaneamente il <ExhaustionIconKeywords:Potere> di tutti i nemici di [Exhaustion:Arg1] punti.] Ottieni [Arg2] punti di Arithmetica, applica [Poison:Arg3] strati di <IntoxicationIconKeywords:Veleno> a tutti i nemici. L'effetto di <ResonanceKeywords:Risonanza> successivamente attivato da sé stessi viene raddoppiato. Scegli: <WitherKeywords1:Fidanzamento> o <WitherKeywords2:Ammaliamento>."
  },
