  Skill_126490_BattleDesc_0 = {
    Text = "Arachne ottiene <Energy:[Energy:Arg1]> Aliemus. Il <ExaltIconKeywords:Risveglio>: \"Annientamento\" viene modificato in: scegli 1 Carta di comando dallo Spazio Ultra, estraila e falla attivare due volte la prossima volta che viene giocata, e fai in modo che la prossima Carta di comando giocata attivi <SingularityKeywords3:Navetta di Singolarità>."
  },
  Skill_126490_BattleDesc_15 = {
