  Skill_130928_Name_1 = {
    Text = "Abissale! Vortice! Mega-Esplosione!"
  },
  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "Balza sul campo di battaglia, un cannone temibile che oscilla allegramente al suo fianco. Nessuna preoccupazione o pericolo ha importanza, perché rispetto al legame dell'amicizia, tutto il resto è insignificante. Amici in difficoltà! Vortice entra in scena!"
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Vortice ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Pesca 1 \"Reload!\". Dopo che Vortice scatena una Caccia, la prossima Esaltazione di Vortice ottiene un bonus aggiuntivo del [Arg2]% ai Danni da tentacolo, accumulabile fino a [Arg3] volte."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Vortice ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Pesca 1 \"Ricarica!\". Dopo che Vortice scatena una Caccia, la sua prossima Esaltazione ottiene un Bonus DAN Tentacolo extra del [Arg2]%, e la prossima Esaltazione infligge <RealDamage:Danno Fisso> pari a [Arg4]% della Salute massima al nemico con la Vita più alta, accumulabile fino a [Arg3] <plural value=\"[Arg3]\" singular=\"volta\" plural=\"volte\">."
  },
  Skill_130929_Desc_0 = {
    Text = "Vortice ottiene [Arg5]% Aliemus Base. <ExaltIconKeywords:Risveglio>: Pesca 1 \"Ricarica!\". Dopo che Vortice Scatena una Caccia, la prossima Esaltazione di Aliemus di Vortice ottiene in aggiunta [Arg2]% Bonus DAN Tentacolo, cumulabile fino a [Arg3] volte."
  },
  Skill_130929_Desc_15 = {
    Text = "Vortice ottiene Aliemus pari a [Arg5]% della sua Base Aliemus. <ExaltIconKeywords:Risveglio>: Pesca 1 \"Ricarica!\". Dopo che Vortice scatena una Caccia, la sua prossima Esaltazione ottiene un Bonus DAN Tentacolo extra del [Arg2]%, e la prossima Esaltazione infligge <RealDamage:Danno Fisso> pari a [Arg4]% della Salute massima al nemico con la Vita più alta, accumulabile fino a [Arg3] <plural value=\"[Arg3]\" singular=\"volta\" plural=\"volte\">."
  },
  Skill_130929_EffectNameList = {
