  Skill_130930_Desc_1 = {
    Text = "<PVPWeaponKeywords:Ruota del destino>: Dopo l'\"Esaltazione\", concedi a sé stessi <Block:[Block:Arg1]> Scudo del Personaggio e <DelayKeywords:Ritardo>: <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_130930_Name_1 = {
    Text = "L'Eden lontano"
  },
  Skill_130931_AwakerSkillBackgroundStory = {
    Text = "Il vortice porta rovina; l'Abisso porta oblio. Una fanciulla che un tempo anelava la luce del sole e l'amicizia fu infine rigettata in un'eterna solitudine. Urla, lamenti, distorsione e collasso—un ciclo senza fine definì il suo tempo nel Moskstraumen. Questo è il ruggito della fame sotto le onde, che divora tutto. Ed è la prova che Vortice l'ha conquistata."
  },
  Skill_130931_BattleDesc_0 = {
    Text = "Dissolvi <BurningKeywords:Bruciatura> da tutte le carte In Mano. Infliggi <Damage:[Damage:Arg1]> Danni a tutti i nemici, infliggendo 2x Danni al nemico con i PV più alti. Sacrifica fino a 3 Tentacoli Permanenti aggiuntivi([Arg4]), ognuno dei quali aumenta il Danno Crit. di questa Esaltazione del +50%.(Tasso Crit. attuale: [Arg5] %. Bonus Danno Tentacolo: [Arg8] %)."
  },
  Skill_130931_BattleDesc_1 = {
    Text = "Dissolvi <BurningKeywords:Bruciatura> da tutte le carte in mano. Infliggi <Damage:[Damage:Arg1]> DAN a tutti i nemici, infliggendo 2x DAN al nemico con i PV più alti. Sacrifica fino a 3 Tentacoli Permanenti aggiuntivi([Arg4]), ognuno dei quali aumenta il Danno Crit. di questa Esaltazione del +50%.(Tasso di Crit. attuale: [Arg5] %. Bonus DAN del Tentacolo: [Arg8] %). Ottieni [Arg6] Padronanza del Reame."
  },
  Skill_130931_BattleDesc_3 = {
    Text = "Rimuovi lo Stato <BurningKeywords:Bruciatura> da tutte le carte in mano. Infligge <Damage:[Damage:Arg1]> punti di Danno a tutti i nemici, infliggendo il triplo del Danno al nemico con la Vita più alta. Sacrifica fino a 3 Tentacoli permanenti aggiuntivi ([Arg4]), ogni Tentacolo aumenta il Danno critico di questa Esaltazione del +50% (Tasso critico attuale: [Arg5]%. Bonus DAN Tentacolo: [Arg8]%). Ottieni [Arg6] punti di Padronanza del Reame; per ogni 20 punti di Aliemus consumati, gli altri Risvegliatori ottengono 1 punto di Aliemus."
  },
  Skill_130931_Desc_0 = {
