  },
  Skill_130946_UnknownName = {
    Text = "Innocenza Annegata"
  },
  Skill_130947_Desc_1 = {
    Text = "Infligge Danno <Damage:[Damage:Arg1]>, <PVPPenetrateKeywords:Perforare>, si potenzia in <PVPDerivativeCardKeywords_28:\"Abissale! Vortice! Mega-Esplosione!\">. Se non causa Uccisione, ottiene [Arg2] strati di <PVPWaterPowerKeyWords:Moskstraumen>."
  },
  Skill_130947_Name_1 = {
    Text = "Abissale! Vortice! Mk. II!"
  },
  Skill_130948_Desc_1 = {
    Text = "Ottieni [Arg1] accumuli di <PVPWaterPowerKeyWords:Vortice> e aggiungi [Arg2] <PVPDerivativeCardKeywords_26:\"Guscio di Marea\"> alla tua mano."
  },
  Skill_130948_Name_1 = {
    Text = "Increspature Vorticose"
  },
  Skill_131102_Desc = {
