  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "\nL'oceano è profondo e sereno, porta con sé il Desiderio di vita e il timore della morte.\nEppure c'è chi sceglie di riempire l'oceano di risate e monellerie — quando Aurita porge un simile invito, il pensiero \"perché non divertirsi un po' con lei\" affiora sempre alla mente, lasciando che una gioia semplice colmi il cuore."
  },
  Skill_132429_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN. Consuma fino a 10 \"Divisione Ghiandolare\" dal Mazzo di Pesca e dalla Pila degli scarti, ognuna fornisce 1 istanza di DAN aggiuntiva. Metti 2 \"Divisione Ghiandolare\" in mano. Aumenta i DAN inflitti da Aurita in questa battaglia di [Arg2]."
  },
  Skill_132429_Desc_2 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> <PunctureDamagewords:Danni Perforanti>. Consuma fino a 10 carte \"Divisione Ghiandolare\" dal Mazzo di Pesca e dalla Pila degli scarti, ciascuna infliggendo un'istanza aggiuntiva di Danno. Metti 2 carte \"Divisione Ghiandolare\" In Mano. Aumenta il Danno inflitto da Aurita in questa battaglia di [Arg2] punti."
  },
  Skill_132429_EffectNameList = {
    Text = "DAN,DAN Successivo▲"
  },
  Skill_132429_Name = {
