  Skill_132435_AwakerSkillBackgroundStory = {
    Text = "La ragazza lasciò con riluttanza l'acquario in bancarotta, e le fu concesso di portare a casa alcune meduse come compenso.\nErano le sue piccole creature preferite, spiriti eterei del mare e fiori di vita eterna.\nCon le dovute cure, avrebbero riempito l'intera vasca! — Un tempo sperava in un tale spettacolo."
  },
  Skill_132435_Desc_0 = {
    Text = "Aurita ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni 1 Tentacolo e aggiungi 2 \"Divisione Ghiandolare\" alla mano. Quando Aurita infligge DAN, [Arg2] Tentacoli attaccano una volta."
  },
  Skill_132435_Desc_15 = {
    Text = "Aurita ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni 1 Tentacolo e aggiungi 2 \"Divisione Ghiandolare\" alla mano. Quando Aurita infligge DAN, [Arg2] Tentacoli attaccano una volta. Il \"Colpo\" di Aurita infligge Danni Perforanti e attacca +2 volte."
  },
