  Skill_133322_Name_1 = {Text = "Colpo"},
  Skill_133323_BattleDesc_1 = {
    Text = "Infligge <Damage:[Damage:Arg4]> danni al nemico in prima fila. Per ogni [Arg2] vita persa, danno +[Arg3]. Recupera una quantità equivalente di vita."
  },
  Skill_133323_Desc_1 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno al nemico in prima fila. Per ogni [Arg2] Vita persa, Danno +[Arg3], e ripristina una quantità equivalente di Vita."
  },
  Skill_133323_Name_1 = {
