  Skill_142695_BattleDesc = {
    Text = "Rimuove il proprio stato di <ExhaustionIconKeywords:Riduzione del potere>. Riduce temporaneamente il <ExhaustionIconKeywords:Potere> di tutti i nemici di [Exhaustion:Arg1] punti. Infligge al nemico con la Vita più bassa un <RealDamage:Danno Fisso> pari al [Arg2]% dei Danni da tentacolo( [Arg3] ); se lo uccide, genera 1 \"Gaunt\" permanente <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> da aggiungere alla mano; è possibile generare al massimo 3 \"Gaunt\" permanenti per battaglia."
  },
  Skill_142695_Desc = {
    Text = "Rimuovi il proprio stato <ExhaustionIconKeywords:Riduzione del potere>. La <ExhaustionIconKeywords:FOR> di tutti i nemici -[Exhaustion:Arg8] temporaneamente. Infliggi <RealDamage:Danno Fisso> pari al [Arg2]% dei Danni da tentacolo al nemico con Vita più bassa. Se questo uccide il bersaglio, genera 1 \"Gaunt\" permanente<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> in mano. Massimo 3 \"Gaunt\" permanenti generati per battaglia."
  },
  Skill_142695_EffectNameList = {
