  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "\"Cosa desideri?\"\nPotere, ordine, ritrovare ciò che era perduto, lavare le offese col Sangue…\nSprofondò in un lungo e cupo silenzio, eppure aveva già la sua risposta: una risposta senza soluzione.\nVoleva che il Sole sorgesse a est e tramontasse a ovest, voleva che Tutto fosse nella Norma."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos ottiene <Energy:[Energy:Arg1]> punti di Aliemus. <ExaltIconKeywords:Risveglio>: per ogni 3 \"Gaunt\" nel mazzo, \"Caccia Implacabile\" ottiene 1 strato aggiuntivo di <BattueKeywords:Caccia in Branco>. Per ogni Carta di Pontos giocata, l'effetto di Riduzione del potere temporanea della prossima \"Caccia Implacabile\" aumenta del [Arg3]%, attivabile al massimo 3 volte per turno."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos guadagna <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Per ogni 2 \"Gaunt\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> nel mazzo, \"Caccia Implacabile\" guadagna 1 stack aggiuntivo di <BattueKeywords:Caccia in Branco>. Per ogni Carta Pontos giocata, l'effetto FOR temporanea▼ della prossima \"Caccia Implacabile\" +[Arg3]%, che si attiva fino a 3 volte per turno. Guadagna +<Energy:[Energy:Arg4]> Aliemus alla 1ª giocata di \"Colpo\" e \"Difesa\" ogni turno."
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos ottiene [Arg2]% di Aliemus Base. <ExaltIconKeywords:Risveglio>: per ogni 3 \"Gaunt\" nel mazzo, \"Caccia Implacabile\" ottiene 1 strato di <BattueKeywords:Caccia in Branco>. Per ogni Carta di Pontos giocata, l'effetto di Riduzione del potere temporanea della prossima \"Caccia Implacabile\" aumenta del [Arg3]%, attivabile al massimo 3 volte per turno."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos guadagna [Arg2]% di Aliemus Base. <ExaltIconKeywords:Risveglio>: Per ogni 2 \"Gaunt\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> nel mazzo, \"Caccia Implacabile\" guadagna 1 stack di <BattueKeywords:Caccia in Branco>. Per ogni Carta Pontos giocata, l'effetto FOR temporanea▼ della prossima \"Caccia Implacabile\" +[Arg3]%, che si attiva fino a 3 volte per turno. Guadagna +<Energy:[Energy:Arg4]> Aliemus alla 1ª giocata di \"Colpo\" e \"Difesa\" ogni turno."
