  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "Né l'orecchio umano né l'attuale Tecnologia di chip d'argento riescono a ricavare alcuna informazione utile dal fischio di caccia di Pontos.\nEppure tutti gli individui assimilati da Ebwynnos sembrano adattarsi molto rapidamente a seguire i comandi de Il Fischio."
  },
  Skill_142846_Desc = {
    Text = "Se è la prima volta che viene usata in questa battaglia, genera 3 tipi diversi di \"Gaunt\" <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> da aggiungere alla mano e ottieni <Block:[Block:Arg1]> punti di Scudo; per ogni 4 Gaunt permanenti posseduti, 1 di essi viene potenziato in \"Gaunt Congiunti\". Altrimenti, pesca 3 \"Gaunt\"."
  },
