  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Ruota del destino>: Quando un alleato muore, ottieni <Energy:[Energy:Arg1]> Aliemus. Quando un alleato viene Rianimato, ottiene <Energy:[Energy:Arg2]> Aliemus. L'effetto di guadagno Aliemus si attiva solo quando l'Aliemus del bersaglio non è pieno, fino a [Arg8] volte. Dopo aver esaurito il conteggio, Distruggi questa Ruota del destino."
  },
  Skill_144438_Name_1 = {
    Text = "Sincronizzazione dell'Anima"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "La fatina e il mago si incrociarono su un pezzo di terra desolata in un angolo di una piccola città.\nLei sorridendo faceva cenno a dei bambini stranieri ben vestiti, mentre il mago aveva gli occhi fissi sul tintinnante braccialetto d'oro al polso della loro madre.\nI loro sguardi si incontrarono nell'aria, e in un istante, ciascuno comprese le intenzioni dell'altro.\nIn questo silenzioso duello, il mago si dimostrò il più abile, riuscendo a spuntarla di misura grazie alla sua lunga esperienza.\nE così, una nuova e splendida impresa di inganni e truffe alzò il sipario."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni 1 accumulo di <WormGrowth1:Sazietà>. Quando infliggi DAN, applica [<Corrosion:Corrosione>:Arg10] accumuli di <Corrosion:Corrosione> al bersaglio.] Rimuovi <BurningKeywords2:Bruciatura> da tutte le carte in Mano. Ottieni <Block:[Block:Arg2]> Scudo. Infliggi <Damage:[Damage:Arg1]> DAN [Arg8] volte a tutti i nemici. Ogni accumulo di <WormGrowth1:Sazietà> aumenta il DAN base dell'Esaltazione e la Generazione di Scudo del [Arg6]%. Consuma tutti gli accumuli di <SacrificialMark1:Offerta>; ogni accumulo aumenta il conteggio dei colpi dell'Esaltazione di 1 e si converte in un numero uguale di accumuli di <WormGrowth1:Sazietà>. Accumuli attuali di <WormGrowth1:Sazietà>: [Arg9]. Accumuli ottenuti in questa battaglia: [Arg11]"
  },
  Skill_144486_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni <WormGrowth2:Sazietà>. Quando infliggi DAN, applica [<Corrosion:Corrosione>:Arg10] accumuli di <Corrosion:Corrosione> al bersaglio.] Rimuovi <BurningKeywords2:Bruciatura> da tutte le carte in Mano. Ottieni <Block:[Block:Arg2]> Scudo. Infliggi <Damage:[Damage:Arg1]> DAN [Arg8] volte a tutti i nemici. Ogni accumulo di <WormGrowth2:Sazietà> aumenta il DAN base dell'Esaltazione e la Generazione di Scudo del [Arg6]%. Consuma tutti gli accumuli di <SacrificialMark1:Offerta>; ogni accumulo aumenta il conteggio dei colpi dell'Esaltazione di 1 e si converte in un numero uguale di accumuli di <WormGrowth2:Sazietà>. Accumuli attuali di <WormGrowth2:Sazietà>: [Arg9]. Accumuli ottenuti in questa battaglia: [Arg11]"
  },
  Skill_144486_Desc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni 1 accumulo di <WormGrowth1:Sazietà>. Quando infliggi DAN, applica [<Corrosion:Corrosione>:Arg10] accumuli di <Corrosion:Corrosione> al bersaglio.] Rimuovi <BurningKeywords2:Bruciatura> da tutte le carte in Mano. Ottieni <Block:[Block:Arg2]> Scudo. Infliggi <Damage:[Damage:Arg1]> DAN [Arg8] volte a tutti i nemici. Ogni accumulo di <WormGrowth1:Sazietà> aumenta il DAN base dell'Esaltazione e la Generazione di Scudo del [Arg6]%. Consuma tutti gli accumuli di <SacrificialMark1:Offerta>; ogni accumulo aumenta il conteggio dei colpi dell'Esaltazione di 1 e si converte in un numero uguale di accumuli di <WormGrowth1:Sazietà>."
  },
  Skill_144486_Desc_3 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni <WormGrowth2:Sazietà>. Quando infliggi DAN, applica [<Corrosion:Corrosione>:Arg10] accumuli di <Corrosion:Corrosione> al bersaglio.] Rimuovi <BurningKeywords2:Bruciatura> da tutte le carte in Mano. Ottieni <Block:[Block:Arg2]> Scudo. Infliggi <Damage:[Damage:Arg1]> DAN [Arg8] volte a tutti i nemici. Ogni accumulo di <WormGrowth2:Sazietà> aumenta il DAN base dell'Esaltazione e la Generazione di Scudo del [Arg6]%. Consuma tutti gli accumuli di <SacrificialMark1:Offerta>; ogni accumulo aumenta il conteggio dei colpi dell'Esaltazione di 1 e si converte in un numero uguale di accumuli di <WormGrowth2:Sazietà>."
