  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "L'avidità è il vero colore della natura umana.\nNessuno può resistere alla tentazione dello zucchero, nemmeno la Fata Madrina in persona.\nCaraboo sorrise a tutta bocca, mostrando una dentatura di denti aguzzi e nerissimi."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Dopo aver usato \"Fornace Cremisi\", la prossima <DerivativeCardKeywords_160:\"Benedizione Miracolosa\"> costa -3 Arithmetica, e ogni opzione di <FaxianKeywords:Scopri> viene aggiornata a un set che contiene 1 carta <DerivativeCardKeywords_152:\"Benedizione\"> in più. Scegli 1 set da mescolare nel tuo Mazzo di Pesca."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Dopo aver usato \"Fornace Cremisi\", la prossima <DerivativeCardKeywords_160:\"Benedizione Miracolosa\"> costa -3 Arithmetica, e ogni opzione di <FaxianKeywords:Scopri> viene aggiornata a un set che contiene 2 carte <DerivativeCardKeywords_152:\"Benedizione\"> in più. Scegli 1 set da mescolare nel tuo Mazzo di Pesca. Dopo aver giocato una carta \"Benedizione\", Fusione Embrionale +10. Questo effetto di fusione aumenta in base ai tuoi PS persi, fino a +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo ottiene [Arg2]% di Base Aliemus. <ExaltIconKeywords:Risveglio>: Dopo aver usato \"Fornace Cremisi\", la prossima <DerivativeCardKeywords_160:\"Benedizione Miracolosa\"> costa -3 Arithmetica, e ogni opzione di <FaxianKeywords:Scopri> viene aggiornata a un set che contiene 1 carta <DerivativeCardKeywords_152:\"Benedizione\"> in più. Scegli 1 set da mescolare nel tuo Mazzo di Pesca."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo ottiene [Arg2]% di Base Aliemus. <ExaltIconKeywords:Risveglio>: Dopo aver usato \"Fornace Cremisi\", la prossima <DerivativeCardKeywords_160:\"Benedizione Miracolosa\"> costa -3 Arithmetica, e ogni opzione di <FaxianKeywords:Scopri> viene aggiornata a un set che contiene 2 carte <DerivativeCardKeywords_152:\"Benedizione\"> in più. Scegli 1 set da mescolare nel tuo Mazzo di Pesca. Dopo aver giocato una carta <Blessing:Benedizione>, Fusione Embrionale +10. Questo effetto di fusione aumenta in base ai tuoi PS persi, fino a +100%."
  },
