  Skill_145675_BattleDesc_3 = {
    Text = "Ottieni <Block:[Block:Arg1]> punti di Scudo, ottieni [Power:Arg2] punti di <PowerIconKeywords:Forza>, consuma tutta la <KuangNu2:Corrente Sotterranea>, ogni stack consumato aumenta lo Scudo e la Forza concessi del 50%, ottieni 1 stack di <ShuZui:Senso di Colpa>."
  },
  Skill_145675_Desc_0 = {
