  Skill_145676_AwakerSkillBackgroundStory = {
    Text = "Quando ogni cavaliere veniva nominato e prestava giuramento, anche l'arma al suo fianco veniva ricoperta di gloria.\nEppure la prima lancia d'argento che era appartenuta a lui — quella investita di una sacra missione — si era da tempo dissolta tra le braci morenti della battaglia.\nTuttavia, poiché era già un uomo gravato dal peccato, pensò che tanto valeva lasciare che quel nero torbido e peccaminoso diventasse la sua nuova arma. In quel modo, si disse, anche se altro sangue l'avesse macchiata, non avrebbe più portato vergogna a coloro che un tempo conosceva."
  },
  Skill_145676_BattleDesc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN, beneficia di un bonus Power del [Arg2]%, ottieni 1 stack di <KuangNu:Ondata Oscura>."
  },
  Skill_145676_BattleDesc_3 = {
