  Skill_146011_AwakerSkillBackgroundStory = {
    Text = "L'arco tracciato dalle lame d'osso è sempre calmo ed elegante.\nSferrare ogni fendente con dedizione è il massimo rispetto che lei tributa al suo Rivale e alla battaglia stessa."
  },
  Skill_146011_BattleDesc_0 = {
    Text = "Infligge <Damage:[Damage:Arg1]> Danno [Arg3] volte. Ottiene <Energy:[Energy:Arg2]> Aliemus."
