  },
  Skill_146015_OverLimitUtlSkillDesc = {
    Text = "Consuma <DerivativeCardKeywords_153:\"Grande Lama: Caduta della Balena\"> per scatenare. Ottieni [Power:Arg3] <PowerIconKeywords:STR>. Infliggi <Damage:[Damage:Arg1]> DAN da Colpo Critico garantito al nemico con il DAN più alto, che beneficia di un Bonus STR del [Arg2]%. Per ogni +1 DAN che <DerivativeCardKeywords_153:\"Grande Lama: Caduta della Balena\"> fa infliggere al bersaglio contro di te, \"Recisione di Mundus\" infligge +[Arg4] DAN. <DerivativeCardKeywords_154:>"
  },
  Skill_146015_PropertyNameList = {
