  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "I ricordi di Ogier sono frammentati a causa del D-fenomeno.\nRicorda le risate al ballo ma dimentica il nome del protagonista del ballo; ricorda il suo addestramento nell'ordine cavalleresco ma non sa perché il duca lo nominò cavaliere in così giovane età; ricorda di essere perito sotto la cavalleria corazzata ma non riesce a ricordare il sorriso di chi stava proteggendo.\nNessuno potrebbe biasimarlo. Aveva adempiuto a tutte le responsabilità di un cavaliere, incluso sacrificare la propria vita per la volontà di proteggere."
  },
  Skill_21615_Desc_0 = {
    Text = "Dissolvi lo stato <FragileIconKeywords:Fragile> su di sé. Ottieni <Block:[Block:Arg1]> scudo. Ottieni [Power:Arg2] <PowerIconKeywords:FOR> Temporanea."
  },
  Skill_21615_Desc_2 = {
    Text = "Se la squadra è attualmente nello Stato <FragileIconKeywords:Fragile>, dissolvilo e ottieni <Block:[Block:Arg3]> Scudo del Personaggio. Ottieni <Block:[Block:Arg1]> Scudo del Personaggio. Ottieni [Power:Arg2] <PowerIconKeywords:FOR> Temporanea."
  },
  Skill_21615_EffectNameList_0 = {
