  },
  Skill_21615_OverLimitUtlSkillDesc_0 = {
    Text = "Rimuovi il proprio Stato <FragileIconKeywords:Fragile>. Ottieni <Block:[Block:Arg1]> punti Scudo. Ottieni [Power:Arg2] punti <PowerIconKeywords:Potere> Temporaneo. Lo Scudo ottenuto è potenziato del 200%. Il numero di colpi inflitti da Ogier aumenta di +1 per 3 turni."
  },
  Skill_21615_OverLimitUtlSkillDesc_2 = {
    Text = "Se sei nello Stato <FragileIconKeywords:Fragile>, dissolvilo e ottieni <Block:[Block:Arg3]> Scudo del Personaggio. Ottieni <Block:[Block:Arg1]> Scudo del Personaggio. Ottieni [Power:Arg2] <PowerIconKeywords:Potere> per questo turno. Aumenta lo Scudo del Personaggio ottenuto del 200%. I colpi di Danno di Ogier +1 per 3 turni."
