  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "\"Avvicinatevi, non siate timidi, lasciate che la maestra del cappello assapori le vostre risate e la vostra gioia.\"\nLa Maestra Casiah batté sulla tesa del suo cappello e, con un botto, ne tirò fuori un grande fascio di nastri e carte.\n\"Scegliete una carta nel vostro cuore. Shh! Non ditelo a nessuno. La Maestra Casiah rivelerà quale è unicamente vostra.\""
  },
  Skill_3977_Desc_0 = {
    Text = "Considerata come \"Colpo\". Scegli 1 carta qualsiasi dallo <DimensionalSpaceIconKeywords:Spazio Ultra> e aggiungila alla tua mano, riducendone il Costo di Arithmetica di 2. Infliggi casualmente <Damage:[Damage:Arg1]> Danno [Arg2] volte e ottieni [Power:Arg3] <PowerIconKeywords:Forza> Temporanea."
  },
  Skill_3977_Desc_3 = {
    Text = "Trattata come \"Colpo\". Scegli 1 carta qualsiasi dallo <DimensionalSpaceIconKeywords:Spazio Ultra> e aggiungila alla tua mano, riducendo il suo Costo di Arithmetica di 2. Infliggi casualmente <Damage:[Damage:Arg1]> Danno [Arg2] volte e ottieni [Power:Arg3] <PowerIconKeywords:Forza> Temporaneo/a. <RippleKeywords:Onda d'Urto Residua>: Mischia 1 <DerivativeCardKeywords_4:\"Intuizione\"> nel Mazzo di Pesca."
