  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "Lignaggio ereditato, considerato eretico dagli altri.\nSolo credendo fermamente nella sua nobiltà e grandezza si può sopravvivere in questo mondo crudele.\nQuel rotolo di mano dello Zio Ornn e la pittoresca città antica sottomarina sono il suo unico sostegno spirituale.\n\"Quando il lignaggio eromperà, mi sarà sicuramente concesso il potere supremo dagli abissi del mare.\""
  },
  Skill_3981_Desc = {
    Text = "Ripristina <Heal:[Heal:Arg3]> Vita e rimuovi <WeaknessIconKeywords:Sintomo: Debolezza> da te stesso, applica [Arg4] <plural value=\"[Arg4]\" singular=\"accumulo\" plural=\"accumuli\"> di <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici. <TentacleInjurieIconKeywords:Danni da tentacolo> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrattacco> +[Counterattack:Arg2]. Prima dell'inizio del prossimo turno, per ogni Attacco subito, comanda 1 Tentacolo per contrattaccare."
  },
  Skill_3981_EffectNameList = {
    Text = "Guarigione,DAN Tentacolo,Contatore"
  },
  Skill_3981_Name = {
    Text = "Stirpe dell'Eresia"
  },
  Skill_3981_OverLimitUtlSkillDesc = {
    Text = "Recupera <Heal:[Heal:Arg3]> punti di Vita e dispella il proprio stato di <WeaknessIconKeywords:Debolezza>, applica [Arg4] strati di <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici. <TentacleInjurieIconKeywords:Danni da tentacolo> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrattacco> +[Counterattack:Arg2]. Prima dell'inizio del prossimo turno, per ogni attacco subito, 1 Tentacolo contrattacca l'attaccante. Fa attaccare 1 Tentacolo 5 volte, ottenendo un Contrattacco pari al 25% del Danno inflitto."
