  Skill_4019_AwakerSkillBackgroundStory = {
    Text = "Proprio come la teoria secondo cui \"l'uno genera il tutto, e il tutto ritorna all'uno,\" un tempo cadde nella trappola dei paradossi."
  },
  Skill_4019_Desc_0 = {
    Text = "Ottieni <Posse:[Arg1]> Keyflare. Colloca nella tua mano le copie temporanee delle ultime 3 diverse Carte di Comando Non-Derivate giocate nel turno precedente, con -1 al Costo di Arithmetica, <DepleteIconKeywords:Consumo>, <NothingnessIconKeywords:Fleeting>. Se non ci sono abbastanza Carte di Comando da collocare nella tua mano, pesca una carta per ogni Carta di Comando mancante."
  },
  Skill_4019_Desc_3 = {
    Text = "Ottieni <Posse:[Arg1]> Keyflare. Colloca nella tua mano le copie temporanee delle ultime 3 diverse Carte di Comando Non-Derivate giocate nel turno precedente, con -1 al Costo di Arithmetica, <DepleteIconKeywords:Consumo>, <NothingnessIconKeywords:Fleeting>. Se non ci sono abbastanza Carte di Comando da collocare nella tua mano, pesca una carta per ogni Carta di Comando mancante. Scegli 1 Posse sbloccato per sostituire il tuo Posse attuale. Il tuo Posse attuale verrà ripristinato dopo aver utilizzato un Posse o alla Fine della Battaglia."
  },
  Skill_4019_EffectNameList = {
