  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Ascolta, è il rintocco della campana a morto per sé stessa.\nNé una cercatrice folle, né un'anima perduta; ha semplicemente scelto la propria fine.\nPetali appassiti danzano nel suo rituale, e il vento marino furioso intona il suo canto funebre.\nDopo il rintocco risonante, il mondo cadde in un breve, mortale silenzio."
  },
  Skill_4154_Desc_0 = {
