  Skill_4278_AwakerSkillBackgroundStory = {
    Text = "Sangue caldo gli colava lungo la guancia. Sogghignò, rivelando zanne affilate come rasoi.\nLa legge della giungla è il fondamento del mondo, e lui sarà l'eterno cacciatore.\nCalpestò i cadaveri, ruggendo in trionfo."
  },
  Skill_4278_Desc_0 = {
