  Skill_4284_AwakerSkillBackgroundStory = {
    Text = "Dice sempre alle reclute: anche quando siete stanchi, anche quando siete deboli, non posate mai la vostra arma. Lasciate che diventi la vostra compagna più fidata e il vostro Scudo più forte.\nSul campo di battaglia, solo chi resta abbastanza vigile sopravvive."
  },
  Skill_4284_BattleDesc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio [Arg2] volte. A fine turno, se In Mano, la prossima giocata genererà Scudo del Personaggio 1 volta in più. Rimuovi <CardKeyWord:Sigillato> da tutti i Risvegliatori."
