  Skill_4284_BattleDesc_1 = {
    Text = "Ottiene <Block:[Block:Arg1]> Scudo del Personaggio [Arg2] volte. A fine turno, se In Mano, la prossima giocata genererà Scudo del Personaggio 1 volta in più. Dissolvi <CardKeyWord:Sigillato> da tutti i Risvegliati. Considerata come \"Difesa.\""
  },
  Skill_4284_Desc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio. Se In Mano alla fine del turno, genera Scudo del Personaggio 1 volta in più la prossima volta che viene giocata. Dissolvi tutti gli stati <CardKeyWord:Sigillato> dei Risvegliatori."
  },
  Skill_4284_Desc_1 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. Se è in mano alla fine del turno, la prossima volta che viene giocata genera Scudo 1 volta in più. Dissolvi tutti gli stati <CardKeyWord:Sigillato> degli Awakener. Considerata come \"Difesa\"."
