  },
  Skill_4287_AwakerSkillBackgroundStory = {
    Text = "Il gladiatore chiuse gli occhi.\nIl suo battito cardiaco, costante e forte, sovrastava il rombo lontano della folla.\nNell'oscurità, la fiamma della carneficina si agitò.\nPulsava, ribolliva, finché non lambì via l'infinito nero.\nIl gladiatore aprì gli occhi. Era finalmente pronto."
  },
  Skill_4287_BattleDesc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno 3 volte. Ottieni <Energy:[Energy:Arg2]> Aliemus. L'Aliemus ottenuto raddoppia se gli HP sono inferiori al 25% ([Arg3])."
  },
  Skill_4287_BattleDesc_2 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN 3 volte. Ottieni <Energy:[Energy:Arg2]> Aliemus. Se i PV sono sotto il 25% ([Arg3]), infliggi 2 colpi aggiuntivi e raddoppia l'Aliemus ottenuto."
  },
  Skill_4287_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN tre volte. Uvhash ottiene <Energy:[Energy:Arg2]> Aliemus, raddoppiati se i PV sono sotto il 25%."
