    Text = "Ottieni [Arg1] Tentacoli. Ottieni [TentaclePower:Arg2] <TentacleInjurieIconKeywords:Danni da Tentacolo> Temporanei e [Power:Arg2] <PowerIconKeywords:FRZ> Temporanea. Ottieni [Arg3]% Tasso critico temporaneo."
  },
  Skill_4288_tempBattleDesc_2 = {
    Text = "Ottieni [Arg1] Tentacoli. Ottieni [TentaclePower:Arg2] <TentacleInjurieIconKeywords:Danni da tentacolo> Temporanei e [Power:Arg2] <PowerIconKeywords:Potere> Temporaneo. Ottieni [Arg3]% di Tasso critico Temporaneo. I Danni da tentacolo ricevuti da tutti i nemici aumentano del 10%, cumulabile fino a 5 volte."
  },
  Skill_4288_tempOverLimitUtlSkillDesc_1 = {
    Text = "Ottieni [Arg1] Tentacoli. Ottieni [TentaclePower:Arg2] punti di <TentacleInjurieIconKeywords:Danni da Tentacolo> Temporanei e [Power:Arg2] punti di <PowerIconKeywords:FRZ> Temporanea. Ottieni [Arg3]% Tasso critico temporaneo. A fine turno, comanda a tutti i Tentacoli di attaccare tutti i nemici 2 volte."
