  Skill_4288_tempOverLimitUtlSkillDesc_2 = {
    Text = "Ottieni [Arg1] Tentacoli. Ottieni [TentaclePower:Arg2] <TentacleInjurieIconKeywords:Danni da tentacolo> Temporanei e [Power:Arg2] <PowerIconKeywords:Potere> Temporaneo. Ottieni [Arg3]% di Tasso critico Temporaneo. I Danni da tentacolo ricevuti da tutti i nemici aumentano del 10%, cumulabile fino a 5 volte. Alla fine del turno, comanda tutti i Tentacoli di attaccare tutti i nemici 2 volte."
  },
  Skill_4289_Desc = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno [AttackTimes:Arg2] volte e ottieni [Arg3] Scudo del Personaggio. Alla fine del tuo turno, ottieni [Arg4] Scudo del Personaggio aggiuntivo per ogni carta in mano."
  },
  Skill_4289_Name = {Text = "Sondaggio"},
  Skill_4290_AwakerSkillBackgroundStory = {
    Text = "La processione trionfale è sempre stata una grande celebrazione per i Romani.\nColombe bianche, foglie d'alloro e coriandoli dorati che volano nell'aria... tutto questo è legato ai guerrieri, eppure non lo è.\nInsieme ai prigionieri dalla Gallia, Alessandria e Partia, fu legato a una pesante croce e portato in parata per le strade.\nQuesto è un classico del trionfo. Il guerriero viene deriso senza sosta, semplicemente perché è considerato un complice sanguinario dell'imperatore defunto.\nVergogna, rabbia o odio? No, niente di tutto questo.\nIl guerriero non ha emozioni né pensieri.\nSente solo l'odore del sangue."
  },
  Skill_4290_BattleDesc_0 = {
    Text = "Uvhash ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Uvhash non è influenzato da <CardKeyWord:Sigillato>. Tasso critico e Danno critico aumentano del [Arg2]%. Se la vita è sotto il 25%, gli effetti raddoppiano."
  },
  Skill_4290_BattleDesc_15 = {
    Text = "Uvhash ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Uvhash è immune a <CardKeyWord:Sigillato>, Tasso critico e Danno critico +[Arg2]%, Danno Finale di \"Inno di Sangue e Sabbia\" +[Arg5]%, con effetto raddoppiato quando la Vita è sotto il 25%."
  },
  Skill_4290_Desc_0 = {
    Text = "Uvhash ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Uvhash non è influenzato da <CardKeyWord:Sigillato>. Tasso critico e Danno critico aumentano del [Arg2]%. Se la vita è sotto il 25%, gli effetti raddoppiano."
