  Skill_4294_Name = {
    Text = "Agonia Finale"
  },
  Skill_4295_AwakerSkillBackgroundStory = {
    Text = "Questi occhi non possono più vedere normalmente.\nAffronta la tempesta del tempo e della realtà, lasciando che il caos ululante tagli e frantumi, diventando infine i suoi occhi.\nUn'altra traccia appartenente a \"Ramona\" sta scomparendo dal suo corpo. Non riesce ad afferrare il sé che le sfugge, così come non riesce a trattenere la vita che scorre dalle sue dita."
  },
  Skill_4295_Desc = {
    Text = "Ottieni [Power:Arg1] <PowerIconKeywords:STR>. Scegli 1 carta dal Mazzo di Pesca e aggiungila alla tua mano, riducendo il suo Costo di Arithmetica di 1. <TimeBeacon:Loop>: Invece, scegli 1 carta dal Mazzo di Pesca o dalla Pila degli scarti e aggiungila alla tua mano, impostando il suo Costo di Arithmetica a 0."
