  Skill_4306_AwakerSkillBackgroundStory = {
    Text = "Lei agirà in Suo nome sulla terra.\nLei otterrà la gloria che Egli merita.\nNel tempo della distruzione, sopporterà un dolore che nessun altro può sopportare.\nLei è l'Esecutrice."
  },
  Skill_4306_Desc_0 = {
    Text = "Miryam ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Limite di Tentacoli e Numero di Tentacoli +1. Infligge 1 accumulo di <WeaknessIconKeywords:Sintomo: Debolezza> e <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici. Tasso critico di \"Colpo\" e \"Pira Eccelsa\" di Miryam +100%. Aggiunge 1 <O07CardKeyWord4:\"Fede eretica\"> alla mano."
