  },
  Skill_4315_AwakerSkillBackgroundStory = {
    Text = [[
Proteggi me. Proteggi me. Proteggi me.
Mostri codardi, come lei, sembrano possedere vita ma sono privi di coscienza.
Melma oscura converge nei suoi servitori, incessantemente guidati dai comandi giorno e notte.]]
  },
  Skill_4315_Desc_0 = {
    Text = "Lily ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: A inizio turno, ottieni il 10% di HP Max come <PainWord:Sopportazione>. Quando Lily applica uno Scudo, infliggi [Poison:Arg2] cariche di <IntoxicationIconKeywords:Veleno> al nemico con più HP."
  },
  Skill_4315_Desc_15 = {
    Text = "Lily ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: A inizio turno, ottieni <PainWord:Sopportare> pari al 10% della Salute massima. Quando Lily applica uno Scudo, infliggi [Poison:Arg2] accumuli di <IntoxicationIconKeywords:Veleno> al nemico con la Vita più alta. L'Esaltazione fa sì che ogni colpo ricevuto in questo turno aumenti l'effetto di consumo di <PainWord:Sopportare> del prossimo \"Colpo di Protezione\" del 40%, accumulabile fino a 5 volte."
  },
