  Skill_4329_AwakerSkillBackgroundStory = {
    Text = "Anche dopo aver assistito alla distruzione della sua patria, e anche dopo che tutto ciò che conosceva è svanito sotto la forza divorante della dissoluzione, si rifiuta di abbandonare la sua ricerca. Il localizzatore emette una luce di ricerca, tentando di trovare coloro che condividono la sua casa.\nDeve esserci qualcuno, deve esserci qualcuno."
  },
  Skill_4329_BattleDesc_0 = {
    Text = "Ottieni <Block:[Block:Arg3]> Scudo, scarta tutte le carte in mano. <TransitionIconKeywords:Salto>: Non scarta più le carte, ottieni <Block:[Block:Arg4]> Scudo e pesca 1 carta."
  },
  Skill_4329_BattleDesc_2 = {
    Text = "Ottieni <Block:[Block:Arg3]> Scudo, scarta tutte le carte in mano, ogni carta scartata conferisce <Block:[Block:Arg2]> Scudo Ritardato. <TransitionIconKeywords:Salto>: Non scarta più le carte, ottieni <Block:[Block:Arg4]> Scudo e pesca 2 carte."
  },
  Skill_4329_Desc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo, scarta tutte le carte in mano e, per ogni carta scartata, lo Scudo ottenuto aumenta del 50%. <TransitionIconKeywords:Balzo>: Non scartare carte e pesca 1 carta; lo Scudo ottenuto aumenta del 100%."
  },
  Skill_4329_Desc_2 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo, scarta tutta la mano; per ogni carta scartata, la Generazione di Scudo aumenta del 50% e ottieni <Block:[Block:Arg2]> punti di Scudo Ritardato. <TransitionIconKeywords:Balzo>: Non scarti più carte e peschi 2 carte, la Generazione di Scudo aumenta del 100%."
  },
