  Skill_4333_Desc = {
    Text = "Ottieni [Arg1] <PowerIconKeywords:FOR>, ottieni <Block:[Block:Arg2]> Scudo del Personaggio."
  },
  Skill_4334_AwakerSkillBackgroundStory = {
    Text = "Un bocciolo che sboccia nel fango nero. Un tempo amato dal giardiniere, un tempo nutrito dalla pioggia e dalla rugiada.\nOra sboccia da solo, sopportando venti feroci che tagliano la sua pelle delicata, piogge torrenziali che flagellano il suo corpo fragile, lame affilate che incidono la sua superficie e lunghi aghi che trafiggono il suo midollo.\nNon importa cosa accada, il mostro gigante dentro di lei sopporterà il dolore al suo posto.\nForse l'unico compagno che le resta ora è quel mostro gigante. D'ora in poi, potrà vivere solo al suo fianco..."
  },
  Skill_4334_BattleDesc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio. Cura [Arg2]%([Arg3]) degli accumuli di <PainWord:Sopportare> come PV e rimuovi <PainWord:Sopportare>. Ogni attacco infligge [Poison:Arg4] accumuli di <IntoxicationIconKeywords:Veleno> all'attaccante per 1 turno."
  },
  Skill_4334_BattleDesc_3 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio. Ripristina [Arg2]%([Arg3]) dei PV in base al numero di accumuli di <PainWord:Sopportare> e rimuovi metà degli accumuli di <PainWord:Sopportare>. Ogni volta che subisci un attacco, infliggi [Poison:Arg4] accumuli di <IntoxicationIconKeywords:Veleno> all'attaccante per 1 turno."
  },
  Skill_4334_Desc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. Ripristina il [Arg2]% degli accumuli di <PainWord:Sopportazione> come PV e rimuovi <PainWord:Sopportazione>. Ogni volta che subisci un attacco, infliggi [Poison:Arg4] accumuli di <IntoxicationIconKeywords:Veleno> all'attaccante per 1 turno."
