  Skill_4337_AwakerSkillBackgroundStory = {
    Text = "Lord Dexter giurò che inizialmente aveva fatto studiare la scherma classica a sua figlia solo per affinarne la grazia — chiaramente, le ambizioni di Ramona andavano ben oltre."
  },
  Skill_4337_BattleDesc = {
