  },
  Skill_4339_AwakerSkillBackgroundStory = {
    Text = "Qualcuno chiese ad Aigis, per metà scherzando, se potesse lavorare a maglia una sciarpa per loro, dato che aveva tutto, dai ferri da maglia al filato, addosso.\nAigis abbassò timidamente la testa. Non disse a nessuno che i ferri da maglia sulla sua testa non erano decorazioni, ma strumenti speciali usati per sopprimere il potere nei suoi occhi.\nQualche giorno dopo, completò una sciarpa colorata usando dei ferri da maglia presi in prestito."
  },
  Skill_4339_Desc_0 = {
    Text = "Aigis ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Dopo che Aigis gioca una carta, applica [Arg2] turni di <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici."
  },
  Skill_4339_Desc_15 = {
    Text = "Aigis ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Dopo che Aigis gioca una carta, infligge [Arg2] <plural value=\"[Arg2]\" singular=\"turno\" plural=\"turni\"> di <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici. Dopo che Aigis rilascia la sua Esaltazione, la sua prossima \"Difesa\" ha effetto 3 volte, e il DAN base della sua Esaltazione +50% aggiuntivo."
  },
  Skill_4339_EffectNameList = {Text = "Aliemus"},
