  },
  Skill_4340_Desc = {
    Text = "Ottieni [Arg3] <PowerIconKeywords:FOR> Temporaneo, infliggi <Damage:[Damage:Arg1]> Danno [AttackTimes:Arg2] volte. Se perdi HP, perdi il potenziamento di <PowerIconKeywords:FOR> Temporaneo."
  },
  Skill_4340_Name = {
    Text = "Taglio alla Gola (Cedimento)"
  },
  Skill_4341_Desc = {
    Text = "Infliggi [AttackTimes:Arg2] volte <Damage:[Damage:Arg1]> DAN."
  },
  Skill_4342_AwakerSkillBackgroundStory = {
    Text = "È difficile dire se i bambini conosciuti come \"topi di strada\" abbiano accettato i topi, o se i veri topi abbiano accettato i bambini di strada, ma questo legame nato per necessità è diventato infrangibile nel corso degli anni.\nChi può dire che gli animali non siano i migliori amici dell'umanità?"
