  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "Passo dopo passo, entrò lentamente nel mare.\nIl mare notturno, che inizialmente le sembrava leggermente freddo sulla pelle, divenne presto caldo come un abbraccio umano.\n\"Il mare mi ha accolta,\" pensò Nymphaea tra sé.\nIn uno stato confuso, vide i sorrisi dei suoi genitori. Nelle profondità del mare, doveva sicuramente esserci la felicità familiare."
  },
  Skill_4375_Desc_0 = {
    Text = "Nymphaea ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Dopo che Nymphaea gioca una carta, ottiene <Energy:[Energy:Arg2]> Aliemus. A fine turno, aumenta la quantità di Veleno inflitta da Nymphaea del [Arg3]%."
