  Skill_4388_AwakerSkillBackgroundStory = {
    Text = "Negli innumerevoli cicli, stringe i legami di attribuzione a sé stessa, sprofondando gradualmente nella palude di causa ed effetto.\nI paradossi lacerano il suo corpo, il caos riempie la sua anima, e nel dolore infinito, afferra un barlume di luce emanato dall'\"ignoto\"."
  },
  Skill_4388_Desc_0 = {
