  Skill_4403_AwakerSkillBackgroundStory = {
    Text = "Innumerevoli ingranaggi si incastrano, azionandosi a vicenda e conferendo al guscio di porcellana la capacità di imitare la vita.\nQuesta è la sua creazione più orgogliosa, uno strumento intricato che non può essere replicato.\nErica non avrebbe mai potuto immaginare che l'automa che porta il suo nome sarebbe diventato la sua seconda vita."
  },
  Skill_4403_Desc_0 = {
    Text = "Erica ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: Quando Erica infligge Danno, ottiene [Power:Arg2] <PowerIconKeywords:FOR> Temporaneo; quando Erica applica uno Scudo, ottiene [Arg3] <AlertIconKeywords:Allerta> Temporaneo."
