  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "Il mago disse: \"Ci sono molti pagani.\nNoi nel Levante sembriamo troppo deboli.\nFratello Uvhash, suona il tuo corno,\ne combatti come un folle.\"\nIl guerriero rispose: \"Qui non ci sono pagani.\nSarete tutti uccisi da me, indipendentemente dalla vostra etnia o fede.\nQuando verrà il momento, i cadaveri copriranno la valle e riempiranno la cima della montagna,\nQuesto sarà il mio tributo al Sangue e alla Sabbia.\""
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Il Danno dei successivi [Inno di Sangue e Sabbia] +[Arg4], moltiplicatore FOR +[Arg3] durante questa battaglia.] Infliggi <Damage:[Damage:Arg1]> Danno a tutti i nemici. Questo Danno beneficia di un moltiplicatore ×[Arg2] di <PowerIconKeywords:FOR>. Uvhash ottiene <Energy:[Energy:Arg5]> Aliemus."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: I successivi \"Inno di Sangue e Sabbia\" rilasciati in questa battaglia infliggono +[Arg4] Danno e moltiplicatore di FOR x[Arg3].] Infligge <Damage:[Damage:Arg1]> Danno a tutti i nemici. La <PowerIconKeywords:FOR> ha effetto x[Arg2] su \"Inno di Sangue e Sabbia\". Ottieni Aliemus pari a 2x la Rigenerazione Aliemus di Uvhash."
  },
  Skill_4579_EffectNameList = {Text = "DAN,DAN▲"},
  Skill_4579_Name = {
    Text = "Inno di Sangue e Sabbia"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Divorazione>: Il DAN dei successivi \"Inno di Sangue e Sabbia\" in questa battaglia è aumentato di [Arg4] punti, e il moltiplicatore di Forza è aumentato di [Arg3] volte.] Infliggi <Damage:[Damage:Arg1]> DAN a tutti i nemici. <PowerIconKeywords:FOR> potenzia \"Inno di Sangue e Sabbia\" di [Arg2] volte. Uvhash ottiene <Energy:[Energy:Arg5]> Aliemus. Riempi la mano con carte \"Stridete, Sangue!\" con Esaurimento e Fugace. Aumenta il numero di istanze di DAN di Uvhash di 1 in questo turno."
  },
  Skill_4579_PropertyNameList = {
