  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Sotto la Chiesa si cela uno spazio nascosto.\n\nIl vescovo si inginocchia davanti alla Tavoletta, recitando le parole segrete tramandate dall'alba della creazione.\n\nRune dimenticate dal tempo emettono un bagliore in risposta, manifestando un enorme fantasma per volontà del vescovo, conferendo la \"Benedizione\" a coloro che ne sono bagnati dalla luce."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:Divorazione>: Ottieni [Power:Arg1] <PowerIconKeywords:FOR> Temporanea, +[Arg4]% Tasso critico temporaneo.] Ottieni <Block:[Block:Arg2]> Scudo. Rendi <VulnerabilityIconKeywords:Vulnerabile> tutti i nemici per 1 turno. Fino all'inizio del prossimo turno, il [Arg3]% del DAN subito sarà convertito in Guarigione della Fornace Cremisi."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni [Power:Arg1] <PowerIconKeywords:FOR> Temporanea, Tasso critico Temporaneo +[Arg4]%.] Ottieni <Block:[Block:Arg2]> Scudo. Applica <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici per 1 turno. Fino all'inizio del prossimo turno, quando attaccato, il [Arg3]% del Danno subito verrà convertito in Guarigione della Fornace Cremisi. Salvador ottiene [Arg5]% Danno critico Temporaneo."
  },
  Skill_4581_EffectNameList = {
    Text = "FRZ Temp.,Scudo del Personaggio,Conversione"
  },
  Skill_4581_Name = {
    Text = "Colui che protegge"
  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni [Power:Arg1] punti <PowerIconKeywords:Potere> Temporaneo, Tasso di crit. temporaneo +[Arg4]%.] Ottieni <Block:[Block:Arg2]> punti Scudo. Applica <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici per 1 turno. Fino all'inizio del prossimo turno, quando si subisce un Attacco, il [Arg6]% del Danno viene convertito in Guarigione per la Fornace Cremisi. Fa sì che il \"Colpo Base\" e la \"Fine della sofferenza\" di Salvador beneficino di un bonus del 100% al Potere. In questa esplorazione, il limite massimo della Fornace Cremisi aumenta del 2% della Salute massima, fino a un massimo del 10%."
  },
  Skill_4581_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Divora>: Ottieni [Power:Arg1] <PowerIconKeywords:FOR> Temporanea, +[Arg4]% Tasso critico temporaneo.] Ottieni <Block:[Block:Arg2]> Scudo. Rendi <VulnerabilityIconKeywords:Vulnerabile> tutti i nemici per 1 turno. Fino all'inizio del prossimo turno, quando subisci un attacco, converti il [Arg6]% dei Danni subiti in Guarigione della Fornace Cremisi. Salvador ottiene [Arg5]% Danno critico temporaneo. Il suo \"Colpo Base\" e \"Fine della Sofferenza\" ottengono un Bonus FOR aggiuntivo del 100%. In questa esplorazione, il limite della Fornace Cremisi +2% dei PV Max, fino al 10%."
  },
