  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Faint è incompleta.\nFaint è pericolosa.\nFaint è maledetta.\nFaint, dalle stelle, è il colore più bizzarro e vibrante."
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Faint ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Immediatamente e permanentemente <TouquKeywords:Rubare> [Arg4] <PowerIconKeywords:STR> da tutti i nemici. Ottieni [Counterattack:Arg3] <plural value=\"[Counterattack:Arg3]\" singular=\"accumulo\" plural=\"accumuli\"> di <RetaliateIconKeywords:Contrattacco>. Il tasso di decadimento della Resistenza per questa battaglia è ridotto dal 50% al 45%. Quando Faint gioca una carta, <TouquKeywords:Rubare> [Arg2] <PowerIconKeywords:STR> da tutti i nemici. Al termine del turno, infliggi <RealDamage:Danno Fisso> pari al 50% del <RetaliateIconKeywords:Contrattacco> di Faint."
  },
  Skill_4615_Desc_0 = {
