  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Uno, due... uno, due...\nPortava un vassoio, muovendosi tra la folla a ritmo leggero.\nGli ospiti bevevano e cantavano senza sosta; lei serviva e sorrideva senza fine.\nQui tutto era dorato. Una sala dorata, vino dorato e abiti dorati.\nKaren adorava l'oro. Sfoggiò il suo ben collaudato sorriso di firma.\n\"Buon appetito, caro ospite—!!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Rimuovi lo stato di <SlowIconKeywords:Stagnazione> da tutte le carte in mano. Ripristina <Heal:[Heal:Arg1]> PV. Aggiungi 1 <DerivativeCardKeywords_42:\"Cucina meravigliosa\"> alla tua mano. Infliggi [Poison:Arg2] accumuli di <IntoxicationIconKeywords:Veleno> a tutti i nemici."
