  Skill_4660_OverLimitUtlSkillDesc_0 = {
    Text = "Rimuove lo Stato <SlowIconKeywords:Stagnazione> da tutte le carte in Mano. Recupera <Heal:[Heal:Arg1]> punti Vita. Inserisce 1 carta <DerivativeCardKeywords_43:\"Cucina meravigliosa\"> nella Mano. Applica [Poison:Arg2] strati di <IntoxicationIconKeywords:Veleno> a tutti i nemici. Mischia 1 carta <DerivativeCardKeywords_42:\"Cucina meravigliosa\"> ciascuna nel Mazzo di Pesca e nella Pila degli scarti."
  },
  Skill_4660_OverLimitUtlSkillDesc_3 = {
    Text = "Rimuovi la condizione di <SlowIconKeywords:Stagnazione> da tutte le carte in mano. Ripristina <Heal:[Heal:Arg1]> HP. Aggiungi 1 <DerivativeCardKeywords_43:\"Cucina meravigliosa\"> alla tua mano. Infliggi [Poison:Arg2] accumuli di <IntoxicationIconKeywords:Veleno> a tutti i nemici. Mischia 1 <DerivativeCardKeywords_43:\"Cucina meravigliosa\"> sia nel Mazzo di Pesca che nella Pila degli scarti."
