  Skill_4662_AwakerSkillBackgroundStory = {
    Text = "La gente ammirava la sua bellezza e invidiava il suo fascino, ma nessuno prestava attenzione a un fiore in boccio.\nOscillando incerta nella natura selvaggia, era in balia degli altri, usata come merce di scambio per l'ascesa del giardiniere.\nSolo quando sbocciò davanti alla corona la gente si rese conto di essere stata trafitta e di sanguinare."
  },
  Skill_4662_BattleDesc_0 = {
    Text = "Infliggi casualmente <Damage:[Damage:Arg1]> DAN [Arg3] volte. Ripristina <Heal:[Heal:Arg2]> PV a fine turno."
