  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "Freddi meccanismi hanno sostituito il cuore, e olio idraulico ha sostituito il sangue nei condotti. Dovrebbe essere fredda, razionale, e agire come le viene ordinato.\nMa una volontà esterna si agitava silenziosamente nel suo guscio. Non aveva bisogno di sangue, né di calore; poteva ardere di malvagità inumana per conto proprio. Diceva: Sottomettiti, creatura vile e insignificante, poi sii distrutta nella mia sfera elettrica incandescente."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Ottieni [Power:Arg1] <PowerIconKeywords:FOR> Temporanea. Ottieni <Posse:[Arg2]> Keyflare. Dissolvi lo stato di <WeaknessIconKeywords:Debolezza> su di sé. Ogni volta che una carta entra nello <DimensionalSpaceIconKeywords:Spazio Ultra>, si trasforma in <DerivativeCardKeywords_14:\"Ritirare: Mecha\">."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Ottieni [Power:Arg1] <PowerIconKeywords:FRZ> Temporaneo. Ottieni <Posse:[Arg2]> Keyflare. Dissolvi lo stato <WeaknessIconKeywords:Debolezza> da te stesso. Aggiungi 1 \"Colpo\" <DepleteIconKeywords:Consumo> di Erica alla tua mano. Ogni volta che una carta entra nello <DimensionalSpaceIconKeywords:Spazio Ultra>, trasformati in <DerivativeCardKeywords_14:\"Ritirare: Mecha\">."
  },
  Skill_4663_Desc_0 = {
    Text = "Ottieni [Power:Arg1] <PowerIconKeywords:FOR> Temporanea. Ottieni Keyflare pari alla Rigenerazione Keyflare di Erica. Dissolvi lo stato di <WeaknessIconKeywords:Debolezza> su di sé. Ogni volta che 1 carta entra nello <DimensionalSpaceIconKeywords:Spazio Ultra>, si trasforma in <DerivativeCardKeywords_14:\"Ritirare: Mecha\">."
  },
  Skill_4663_Desc_1 = {
    Text = "Ottieni [Power:Arg1] <PowerIconKeywords:FRZ> Temporaneo. Ottieni Keyflare pari alla Rigenerazione Keyflare di Erica. Dissolvi lo stato <WeaknessIconKeywords:Debolezza> da te stesso. Aggiungi 1 \"Colpo\" con <DepleteIconKeywords:Consumo> assegnato da Erica alla tua mano. Ogni volta che una carta entra nello <DimensionalSpaceIconKeywords:Spazio Ultra>, trasformati in <DerivativeCardKeywords_14:\"Ritirare: Mecha\">."
  },
