  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "Una pestilenza invisibile porta silenziosamente sofferenza e follia senza fine.\n\nIl vescovo non riesce a dormire la notte, profondamente addolorato dalla sua incapacità di alleviare la sofferenza della gente.\n\n\"O Misericordioso Creatore, salvali. Sono disposto a sopportare tutto il loro dolore e la loro angoscia.\"\n\nCosì, il Padre Supremo gli conferì la \"Benedizione\", permettendogli di impugnare la Tavoletta incisa con la Scrittura, compiendo atti di soccorso."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador ha ottenuto <Energy:[Energy:Arg1]> punti di follia. <ExaltIconKeywords:Risveglio della Gnosi>: Metti 1 carta di <B02AFKeyWord:L'amore è protezione> nella tua mano. Alla fine del turno, ottieni [Power:Arg2] punti <PowerIconKeywords:Potenza>."
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Piazza 1 <B02AFKeyWord:L'amore è protezione> in mano. A fine turno, ottieni [Power:Arg2] <PowerIconKeywords:FOR>. Fornace Cremisi accumulata da \"Colui che protegge\" e \"Benedette siano le ossa\" +25%, e quando \"Liberazione\" è selezionata per \"Fine della sofferenza,\" ogni 1% di Salute massima consumata dalla Fornace Cremisi concede +5% Danno Finale."
  },
