  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "È un vasto Labirinto che trascende tutte le dimensioni.\nI viaggiatori che si avventurano nel Labirinto devono affrontare una transazione sgarbata.\nSe rispondi \"no\", resterai intrappolato nel Labirinto per sempre.\nSe rispondi \"sì\", ti verrà impiantata una progenie blasfema e tutti i tuoi ricordi saranno cancellati.\nCosa? Chiedi quali siano i dettagli della transazione?\nNessuno conosce i dettagli della transazione, incluso il pallido Signore del Labirinto.\nUna transazione è solo una transazione."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:Divorare>: Ottieni [Power:Arg1] <PowerIconKeywords:FOR> e [Arg4] <AlertIconKeywords:Allerta>.] Ottieni <Block:[Block:Arg2]> Scudo del Personaggio. Infliggi [Poison:Arg3] accumuli di <IntoxicationIconKeywords:Veleno> a tutti i nemici."
  },
