  },
  Skill_4667_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Divorazione>: Ottieni [Power:Arg1] <PowerIconKeywords:FOR> e [Arg4] <AlertIconKeywords:Allerta>.] Ottieni <Block:[Block:Arg2]> Scudo. Infliggi [Poison:Arg3] cariche di <IntoxicationIconKeywords:Veleno> a tutti i nemici. Pesca 2 Carte di comando DIF non-Colpo di Agrippa, e riduci il Costo di Arithmetica di 2 Carte di comando DIF non-Colpo di Agrippa in mano di 1 per questo turno."
  },
  Skill_4667_PropertyNameList = {
