  Skill_4680_AwakerSkillBackgroundStory = {
    Text = "Il vento di montagna fruscia tra le ossa del labirinto, sospirando.\nLei sente le grida dei viaggiatori smarriti e lascia andare il suo 8.001° sbadiglio.\nSorseggia il dolore, catalogandolo ed esponendolo.\nSolo un problema: nessuno conosce il suo capolavoro; lei è l'unico pubblico.\nSigh—!\nSeduta nella parte più profonda del labirinto, sbadiglia ancora una volta."
  },
  Skill_4680_Desc_0 = {
    Text = "Agrippa ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Il <IntoxicationIconKeywords:Veleno> inflitto da Agrippa aumenta del 50%. Alla fine del turno, ottieni <Block:[Block:Arg2]> Scudo."
