  Skill_4703_Desc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio e infliggi [Poison:Arg2] accumuli di <IntoxicationIconKeywords:Veleno> a tutti i nemici. Per ogni 1% di Resistenza alla Morte di Lily, lo Scudo base aumenta dello 0,25%. Fino all'inizio del prossimo turno, ottieni [Arg3] accumuli di <PainWord:Sopportare> per ogni attacco subito."
  },
  Skill_4703_Desc_1 = {
