  Skill_4750_Desc_0 = {
    Text = "Thais ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni immediatamente 1 carta <DerivativeCardKeywords_10:Figlio Sacro>. Ogni volta che lanci una Posse, trasforma un Embrione in mano in un <DerivativeCardKeywords_10:Figlio Sacro>."
  },
  Skill_4750_Desc_15 = {
