  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "Le fiamme si propagarono, tingendo il baldacchino del teatro di un verde smeraldo, come le acque serene e limpide di un lago al mattino.\nQuanti sono venuti inseguendo questa silhouette smeraldina, mentre altri trascurano la danza fluida e potente, vedendo solo le braccia d'alabastro appena rivelate e le scene immaginate sotto la gonna.\nEppure la danzatrice resta semplicemente lì, come congelata, in una postura di quasi-morte divorata dalle fiamme verdi."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Per ogni [Arg2] <plural value=\"[Arg2]\" singular=\"istanza\" plural=\"istanze\"> di Danno inflitto da Liz, metti una <DerivativeCardKeywords_18:\"Fiamme Verdi\"> con <DepleteIconKeywords:Extenuazione> in mano, fino a 3 volte per turno."
