  Skill_4821_AwakerSkillBackgroundStory = {
    Text = "Il suo labirinto si estende in ogni angolo del mondo.\nCi sono ingressi nelle foreste fitte, sotto le biblioteche e in fondo al mare.\nAffidandosi a quelle anime sfortunate che si avventurano nel labirinto, riesce a malapena a tracciare un profilo del mondo.\nI viaggiatori si perdono nei corridoi in continuo mutamento, mentre lei si perde nelle storie in costante evoluzione.\nSa tutto, eppure non potrà mai lasciare il labirinto."
  },
  Skill_4821_Desc_0 = {
    Text = "Infliggi <Damage:[Damage:Arg1]> DAN e <IntoxicationIconKeywords:Veleno> in pari quantità. Ogni volta che Divorare viene attivato, sposta \"Spirale Incolore\" dalla Pila degli scarti alla tua mano."
