  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "Nel suo vagabondare senza fine, Tintura ha già dimenticato il nome della sua patria.\nNel lungo scorrere del tempo, il cosmo ha dimenticato il nome di quel pianeta morto.\nQuei pianeti sono chiamati collettivamente \"pianeti desolati\", come innumerevoli pianeti dissolti e abbandonati.\nIl suo canto potrebbe essere l'ultima eco di quel pianeta d'oltremondo."
  },
  Skill_4822_Desc_0 = {
    Text = "Tintura ottiene <Energy:[Energy:Arg1]> Aliemus, <ExaltIconKeywords:Risveglio>: Il danno base di \"Colpo\" di Tintura aumenta del [Arg2]%. Tutte le carte di Tintura ottengono un effetto casuale, che viene rimosso al termine della battaglia."
  },
  Skill_4822_Desc_15 = {
    Text = "Tintura ottiene <Energy:[Energy:Arg1]> Aliemus, <ExaltIconKeywords:Risveglio>: Danno base dei \"Colpo\" di Tintura +[Arg2]%, tutte le carte di Tintura ottengono 1 effetto casuale, che verrà rimosso alla fine della battaglia. La prima volta che Tintura gioca un \"Abilità\" ogni turno, genera 1 \"Colpo\" Temporaneo con Costo di Arithmetica 0, gli effetti casuali di questo \"Colpo\" x2."
  },
