  Skill_59478_AwakerSkillBackgroundStory = {
    Text = "Se un'anima potesse essere scomposta, i suoi componenti sarebbero note musicali? Alti e bassi, veloci e lenti, le grida della rinascita e i lamenti della morte risuonano insieme. Ascolta, canta a gran voce — questo è il preludio che raffigura l'essenza della tua anima."
  },
  Skill_59478_BattleDesc = {
    Text = "Infliggi casualmente [Arg2] istanze di <Damage:[Damage:Arg1]> <PunctureDamagewords:Danni Perforanti>, ogni colpo ha il 50% di probabilità di applicare casualmente 1 <MysterydebuffKeywords:Debuff meraviglioso> sul bersaglio. Se il Costo di Arithmetica è 0 al momento dell'utilizzo, infligge 2 colpi aggiuntivi."
  },
  Skill_59478_Desc = {
