  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "Canta, o dea! Canta del destino delle figlie di Delo:\nColmo di sangue e lacrime, rabbia e disperazione.\nIl suo odio brucia tutto ciò che la circonda, e alla fine,\nPorta la sua stessa rovina."
  },
  Skill_61123_Desc_0 = {
    Text = "Helot-catena ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Metti una \"<DerivativeCardKeywords_65:Catene Cremisi>\" nella mano, e le Carte di comando di Helot-catena ottengono \"<RetainIconKeywords:Conservare>\". A inizio turno, il Danno base di Helot-catena +[Arg2]% per questa battaglia."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot-catena ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Metti una \"<DerivativeCardKeywords_65:Catene Cremisi>\" in mano, e le Carte di comando di Helot-catena ottengono \"<RetainIconKeywords:Conservare>\". A inizio turno, il DAN base di Helot-catena +[Arg2]% per questa battaglia. Dopo aver scatenato l'Esaltazione \"Catene Sanguigne\", concedi a ogni Carta di comando unica di \"Helot-catena\" in mano 35 accumuli di <TempPowerKeywords:Potenziamento Temporaneo>."
  },
