  Skill_70142_Name = {Text = "Sopore"},
  Skill_70286_Desc_1 = {
    Text = "<PVPWeaponKeywords:Ruota del destino>: A fine turno, aumenta il Danno, la Guarigione e lo Scudo del Personaggio delle carte \"Abilità\" del Portatore nella tua mano del [Arg1]%."
  },
  Skill_70286_Name_1 = {
    Text = "Trono di Pietra Azzurra"
  },
  Skill_70299_AwakerSkillBackgroundStory = {
    Text = "La destinazione che ha cercato per tutta la vita ora attende, una porta nera come la pece che sussurra promesse.\nPrima di aprirla, ha immaginato 372 possibilità di verità.\nDopo, ne è rimasta solo la 373ª, quella che temeva.\nNessuna scelta rimasta. Cade.\nChe terribile sfortuna... per lei, e per il mondo intero."
  },
  Skill_70299_BattleDesc = {
    Text = "Gli altri Risvegliatori ottengono <Energy:[Energy:Arg1]> Aliemus, applicano [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"accumulo\" plural=\"accumuli\"> di <IntoxicationIconKeywords:Veleno> a tutti i nemici e aumentano temporaneamente l'Amplificazione del Danno del team del [Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Gli altri Risvegliatori ottengono <Energy:[Energy:Arg1]> Aliemus, applicano [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"accumulo\" plural=\"accumuli\"> di <IntoxicationIconKeywords:Veleno> a tutti i nemici e aumentano temporaneamente l'Amplificazione del Danno del team del [Arg3]%. \"Forma Finale\": Pesca 3 carte aggiuntive, ottieni 3 Arithmetica, attiva il 50% del <IntoxicationIconKeywords:Veleno> su tutti i nemici e aumenta l'Aliemus Base di \"Doll: Inferno\" di 50, fino a 3 volte."
  },
  Skill_70299_EffectNameList = {
    Text = "Aliemus,Veleno,Amp. Danni"
  },
  Skill_70299_Name = {
    Text = "Terminale di Verità e Abisso"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Gli altri Risvegliatori ottengono <Energy:[Energy:Arg4]> Aliemus, applicano [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"accumulo\" plural=\"accumuli\"> di <IntoxicationIconKeywords:Veleno> a tutti i nemici, aumentano temporaneamente l'Amplificazione del Danno del team del [Arg3]% e aumentano il <IntoxicationIconKeywords:Veleno>, il <RetaliateIconKeywords:Contrattacco> e il DAN base di tutti i Risvegliatori del 10%. Nelle Battaglie Boss, ottieni un accumulo aggiuntivo di \"Finale\"."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,ATT*GrowValue2,$GrowValue3%"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "La capsula cremisi si gonfia sotto la corazza meccanica mentre il risonatore d'ottone vibra, tessendo un alveare di difese.\nGli impulsi miceliari squarciano l'aria; la nebbia acida incide avvertimenti nella carne. I raggi taglia-memorie brillano incandescenti—oltrepassa il confine, e i tuoi resti tremanti finiranno in una capsula di Petri."
  },
  Skill_70300_BattleDesc = {
    Text = "Ottiene <Block:[Block:Arg1]> Scudo del Personaggio. Ottiene <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70300_Desc = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo. \"Doll: Inferno\" ottiene <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70300_EffectNameList = {
    Text = "Scudo del Personaggio,Aliemus"
  },
  Skill_70300_Name = {Text = "Difesa"},
  Skill_70300_PropertyNameList = {
    Text = "DEF*GrowValue1,$GrowValue2"
  },
  Skill_70301_AwakerSkillBackgroundStory = {
    Text = [[
Le pinze sono reliquie del suo passato, del suo sangue. Un potere a cui non ha mai rinunciato.
Quando affondano nel petto di un nemico, il suo sorriso sboccia come una ferita... cosa significa? Solo i morti potrebbero dirlo, e loro non parlano.]]
  },
  Skill_70301_BattleDesc = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno. Ottieni <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70301_Desc = {
    Text = "Infliggi <Damage:[Damage:Arg1]> Danno. \"Doll: Inferno\" ottiene <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70301_EffectNameList = {
    Text = "DAN,Aliemus"
  },
  Skill_70301_Name = {Text = "Colpo"},
  Skill_70301_PropertyNameList = {
    Text = "ATK*GrowValue1,$GrowValue2"
  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = "Si sacrificò, aprendo un varco verso la verità nascosta. \nQuando ritirò la mano, la sua anima gocciolava come cera fusa."
  },
  Skill_70302_BattleDesc_0 = {
    Text = "\"Doll: Inferno\" ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Alla fine del turno, recupera <Heal:[Heal:Arg2]> Vita e ottiene <Energy:[Energy:Arg4]> Aliemus. \"Forma Finale\": Non recupera più Vita; infligge invece <IntoxicationIconKeywords:Veleno> al [Arg3]% a tutti i nemici."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "\"Doll: Inferno\" ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Per ogni accumulo di \"Finale\", Amplificazione del Danno +8%. \"Fine dell'Illusione\" concede a tutti i Risvegliatori il 30% di Aliemus base. A fine turno, recupera <Heal:[Heal:Arg2]> Vita e ottiene <Energy:[Energy:Arg4]> Aliemus. \"Forma Finale\": Non recupera più Vita, attiva invece [Arg3]% <IntoxicationIconKeywords:Veleno> su tutti i nemici."
  },
  Skill_70302_Desc_0 = {
    Text = "\"Doll: Inferno\" ottiene <Energy:[Energy:Arg1]> punti di Follia. <ExaltIconKeywords:Risveglio della Gnosi>: Alla fine del turno, recupera <Heal:[Heal:Arg2]> punti di Vita e ottiene Follia pari alla propria ricarica di Follia. \"Forma Finale\": Non recupera più Vita, ma infligge <IntoxicationIconKeywords:Veleno> al [Arg3]% a tutti i nemici."
  },
  Skill_70302_Desc_15 = {
    Text = "\"Doll: Inferno\" ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Per ogni accumulo di \"Finale\", Amplificazione del Danno +8%. \"Fine dell'Illusione\" conferisce a tutti i Risvegliatori il 30% di Aliemus Base. Alla fine del turno, recupera <Heal:[Heal:Arg2]> Vita e ottiene Aliemus pari alla Rigenerazione di Aliemus. \"Forma Finale\": Non recupera più Vita, ma infligge <IntoxicationIconKeywords:Veleno> al [Arg3]% a tutti i nemici."
  },
  Skill_70302_EffectNameList = {
    Text = "Aliemus,Guarigione,Attivazione Veleno%"
  },
  Skill_70302_Name = {
    Text = "Morbo dell'Anima"
  },
  Skill_70302_PropertyNameList = {
    Text = "$GrowValue1,COS*GrowValue2,$GrowValue3%,"
  },
  Skill_70303_AwakerSkillBackgroundStory = {
    Text = "Se l'umanità è già su una strada senza ritorno verso l'annientamento, è un atto di misericordia darle una piccola spinta?\nChe la fine giunga in un istante. Che il dolore si cristallizzi. Che gli amanti si stringano l'un l'altro mentre l'oblio li avvolge. \nSe nulla fa male al finale, potrebbe essere, finalmente, il paradiso?"
  },
  Skill_70303_BattleDesc_0 = {
    Text = "Infliggi <RealDamage:Danno Fisso> pari al 30% della loro Salute massima a tutti i nemici (minimo [Arg2]). Dopo l'uso, le abilità specifiche di \"Bambola: Inferno\" passano alla \"Forma Finale\"."
