  Skill_78784_Desc = {
    Text = "Per ogni 1 accumulo di \"Simbiosi\" rimosso, applica 1 accumulo di \"Fissazione fobica\" a tutti i nemici. Ogni accumulo di \"Fissazione fobica\" riduce i danni inflitti del 3%."
  },
  Skill_78784_Name = {
    Text = "Conversione: Fissazione Fobica"
  },
  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "\"Per favore, dimmi, chi è il vero te?\"\nChiese con un sorriso.\nIl povero paziente naturalmente non poteva rispondere, poiché la sua memoria era stata alterata, e più cercava, più si avvicinava alla presenza terrificante impiantata nella sua memoria—fino a quando la sua cognizione non crollava completamente e diventava un mostro."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Rimuovi tutta la tua <AnalysisKeywords0:Simbiosi>, poi trasformala in <D13AFKeyWord2:Trauma Psichico> o <D13AFKeyWord1:Fissazione Fobica> su tutti i nemici [Arg6] <plural value=\"[Arg6]\" singular=\"volta\" plural=\"volte\">. Infligge <Damage:[Damage:Arg1]> Danno a tutti i nemici e ottieni <Posse:[Arg3]> Keyflare."
  },
  Skill_78785_BattleDesc_2 = {
    Text = "Rimuovi tutta la tua <AnalysisKeywords0:Simbiosi>, poi trasformala in <D13AFKeyWord2:Trauma Psichico> o <D13AFKeyWord1:Fissazione Fobica> su tutti i nemici, aumentando il Danno base di Clementine del 3% per ogni accumulo rimosso. Infligge <Damage:[Damage:Arg1]> Danno a tutti i nemici [Arg6] <plural value=\"[Arg6]\" singular=\"volta\" plural=\"volte\"> e ottieni <Posse:[Arg3]> Keyflare."
  },
  Skill_78785_BattleDesc_3 = {
    Text = "Rimuovi tutta la tua <AnalysisKeywords0:Simbiosi>, poi trasformala in <D13AFKeyWord2:Trauma Psichico> o <D13AFKeyWord1:Fissazione Fobica> su tutti i nemici, aumentando il Danno base di Clementine del 3% per ogni accumulo rimosso. Infligge <Damage:[Damage:Arg1]> Danno a tutti i nemici [Arg6] <plural value=\"[Arg6]\" singular=\"volta\" plural=\"volte\"> e ottieni <Posse:[Arg3]> Keyflare."
  },
  Skill_78785_Desc_0 = {
    Text = "Rimuovi tutta la tua <AnalysisKeywords0:Simbiosi>, poi trasformala in <D13AFKeyWord2:Trauma Psichico> o <D13AFKeyWord1:Fissazione fobica> su tutti i nemici. Infliggi <Damage:[Damage:Arg1]> DAN a tutti i nemici. Ottieni Keyflare pari al [Arg2]% della Rigenerazione Keyflare di Clementine."
  },
  Skill_78785_Desc_2 = {
