  Skill_83574_BattleDesc = {
    Text = "Rimuove tutti gli accumuli di \"Salpa l'Ancora\" ([Arg1]). Per ogni accumulo rimosso, Danno Finale +[Arg2]%, e tutti i Risvegliatori guadagnano [Arg3] Aliemus.\nSe vengono rimossi 5 o più accumuli di \"Salpa l'Ancora\" contemporaneamente, rende <VulnerabilityIconKeywords:Vulnerabile> tutti i nemici per 1 turno, infliggendo loro <RealDamage:Danno Fisso> pari al [Arg4]% dei loro PS persi."
  },
  Skill_83574_Desc = {
    Text = "Rimuove tutti gli accumuli di \"Salpa l'Ancora\". Per ogni accumulo rimosso, Danno Finale +10%, e tutti i Risvegliatori guadagnano 5 Aliemus.\nSe vengono rimossi 5 o più accumuli di \"Salpa l'Ancora\" contemporaneamente, infligge \"Vulnerabile\" a tutti i nemici per 1 turno, infliggendo loro <RealDamage:Danno Fisso> pari al 35% dei loro PS persi."
  },
  Skill_83574_Name = {Text = "Archor Off"},
  Skill_83575_BattleDesc = {
    Text = "Rimuovi tutti gli accumuli di \"Ormeggio\" ([Arg1]). Per ogni accumulo rimosso, Resistenza alla Morte + [Arg2]%, ottieni [Arg3] Arithmetica e pesca [Arg4] carte.\nSe vengono rimossi 5 o più accumuli di \"Ormeggio\" in una volta, ottieni [Arg5] accumuli di Barriera Temporanea tramite <ParcloseIconKeywords:Barriera>."
  },
  Skill_83575_Desc = {
    Text = "Rimuovi tutti gli accumuli di \"All'Ancora\". Per ogni accumulo rimosso, \"Resistenza\" +15%, ottieni 1 Arithmetica, pesca 1 carta.\nSe vengono rimossi 5 o più accumuli di \"All'Ancora\" contemporaneamente, ottieni 1 accumulo di \"Barriera\"."
  },
  Skill_83575_Name = {
    Text = "Riposo in Porto"
  },
  Skill_83576_BattleDesc = {
    Text = "Scegli: \"Archor Off\" ([Arg1]) o \"Riposo in Porto\" ([Arg2]). <DepleteIconKeywords:Consumo> quando scartata."
  },
  Skill_83576_Desc = {
    Text = "Scegli: \"Archor Off\" o \"Riposo in Porto.\" Scarta <DepleteIconKeywords:Consumo>."
  },
  Skill_83576_Name = {
    Text = "Il Dilemma del Navigatore"
  },
  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "L'acqua salata sconfinata la divorò, eppure la protesse anche.\nIn quella soffocante sensazione di sprofondamento, percepì l'oceano profondo, fondendosi con l'oceano profondo.\nUn giorno, il mare sarà completamente calmo, e a ogni nave che solcherà la sua superficie sarà concessa la pace.\nLei attende quel giorno, il giorno in cui il suo Regno divino discenderà."
  },
  Skill_83779_Desc_0 = {
    Text = "Corposant ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni 1 Tentacolo, aggiungi 2 carte \"<DerivativeCardKeywords_106:Pilota>\" in mano. Dopo essere passato alla posizione \"Mare Tranquillo\", ottieni <Block:[Block:Arg2]> Scudo, con un tempo di ricarica di 3 turni."
  },
  Skill_83779_Desc_15 = {
    Text = "Corposant ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni 1 Tentacolo, aggiungi 2 \"<DerivativeCardKeywords_106:Pilota>\" in mano. Per il primo \"Castigo del Fulmine\" e \"Semaforo Sinistro\" che Corposant gioca ogni turno, metti 1 \"Pilota\" aggiuntivo in mano. Effetto di \"<DerivativeCardKeywords_106:Pilota>\" +50%. Dopo essere passato alla posizione \"Mare Tranquillo\", ottieni <Block:[Block:Arg2]> Scudo, con un tempo di ricarica di 3 turni."
  },
  Skill_83779_EffectNameList = {
    Text = "Aliemus,Scudo del Personaggio"
  },
  Skill_83779_Name = {
    Text = "Sommerso nel Profondo"
  },
  Skill_83779_PropertyNameList = {
    Text = "$GrowValue1,DIF*GrowValue2"
  },
  Skill_83780_AwakerSkillBackgroundStory = {
    Text = "Le nuvole informeranno dei cambiamenti del clima, e le onde parleranno delle trasformazioni delle correnti oceaniche, ma quando la tempesta arriva davvero, anche la più possente delle navi può solo andare alla deriva tra i flutti, inerme.\n In quel momento, i calcoli e la guida del navigatore sono l'ultimo rifugio per tutti i sopravvissuti.\n Perciò, adempi al tuo dovere, anche se colpito dal fulmine, per far brillare un barlume di luce attraverso il dolore, indicando la via verso la riva.\n Questa è la missione che devi compiere."
  },
  Skill_83780_BattleDesc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo e [Arg2] Tentacoli Temporanei. Scarta tutte le carte in mano e pesca lo stesso numero di carte."
  },
  Skill_83780_BattleDesc_3 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo e [Arg2] Tentacoli Temporanei. Rendi <VulnerabilityIconKeywords:Vulnerabile> tutti i nemici per 1 turno, Danno Crit. temporaneo + [Arg5] %. Scarta tutta la Mano e pesca un numero uguale di carte."
  },
  Skill_83780_Desc_0 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo e [Arg2] Tentacoli Temporanei. Scarta tutte le carte in mano e pesca lo stesso numero di carte."
  },
  Skill_83780_Desc_3 = {
    Text = "Ottieni <Block:[Block:Arg1]> Scudo del Personaggio e [Arg2] Tentacoli Temp. <VulnerabilityIconKeywords:Vulnerabile> a tutti i nemici per 1 turno, Danno critico temporaneo + [Arg3]%, e ogni volta che la Resistenza alla Morte si attiva in questa battaglia, aumenta di un ulteriore [Arg4]%. Scarta tutta la Mano e pesca un numero uguale di carte."
  },
  Skill_83780_EffectNameList = {Text = "Scudo"},
  Skill_83780_Name = {
    Text = "Navigare le Maree Spezzate"
  },
  Skill_83780_OverLimitUtlSkillDesc_0 = {
    Text = "Scarta tutte le carte in mano e pesca un numero equivalente di carte, attivando 1 volta in più l'effetto \"Scossa Residua\" delle carte scartate. Ottieni <Block:[Block:Arg1]> punti di Scudo, [Arg2] Tentacoli temporanei e [Arg2] Tentacoli permanenti."
  },
  Skill_83780_OverLimitUtlSkillDesc_3 = {
    Text = "Rendi <VulnerabilityIconKeywords:Vulnerabile> tutti i nemici per 1 turno, Danno Crit. Temporaneo +[Arg5]%. Scarta tutte le carte in mano e pesca un numero uguale di carte, attiva l'effetto \"Onda d'Urto Residua\" delle carte scartate un'ulteriore volta. Ottieni <Block:[Block:Arg1]> Scudo, [Arg2] Tentacoli Temporanei e [Arg2] Tentacoli Permanenti."
  },
