  Skill_95811_Desc_0 = {
    Text = "Doresain ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni [Power:Arg2] <PowerIconKeywords:STR>, e i danni inflitti da Doresain ottengono un bonus STR aggiuntivo del [Arg3]%. La prima volta che Doresain ottiene un'Uccisione in ogni turno, infliggi <RealDamage:Danno Fisso> pari al 50% del danno in eccesso agli altri nemici."
  },
  Skill_95811_Desc_15 = {
    Text = "Doresain ottiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Risveglio>: Ottieni [Power:Arg2] <PowerIconKeywords:STR>. I danni inflitti da Doresain ottengono un Bonus STR extra del [Arg3]%. Infliggi Danno Fisso pari al [Arg4]% della Vita attuale a tutti i nemici. Dopo la prima Uccisione di Doresain in ogni turno, infliggi <RealDamage:Danno Fisso> agli altri nemici pari al 100% del danno in eccesso."
  },
